// A freshly loaded script must also load its matching stylesheet.
for(const link of document.querySelectorAll('link[rel="stylesheet"]')){const u=new URL(link.href,location.href);if(u.pathname.endsWith('/docs/docs.css')&&u.searchParams.get('v')!=='learning-r3.3'){u.searchParams.set('v','learning-r3.3');link.href=u.href}}
function localLinks(){for(const a of $$('a[href]')){const raw=a.getAttribute('href');if(!raw||raw.startsWith('#')||/^(https?:|mailto:)/i.test(raw)&&a.origin!==location.origin)continue;const u=new URL(raw,location.href);if(!u.pathname.endsWith('.html'))continue;u.searchParams.set('lang',lang);a.href=u.href;}}
// Shared navigation and current release label on all reference pages.
const side=document.querySelector('#doc-side');
side.querySelector('.side-kicker').textContent='OVERDRIVE / 0.26.0';
const crumb=document.querySelector('.crumb > span:last-child');if(crumb&&/^0\.(24|25)$/.test(crumb.textContent))crumb.textContent='0.26';
const meta=document.querySelector('.lib-meta > span:first-child');if(meta&&/^(ASCENSION 0\.24|EVOLUTION 0\.25)$/.test(meta.textContent))meta.textContent='OVERDRIVE 0.26';
const guide=side.querySelector('nav[aria-label="Guides"]');
for(const [file,label] of [['genesis','GENESIS R2'],['update','UPDATE R1']]){let a=guide.querySelector('a[href$="'+file+'.html"]');if(!a){a=document.createElement('a');a.href=root+file+'.html';guide.append(a);}a.textContent=label;}
const libs=side.querySelector('.side-libs');
for(const [name,before,count] of [['queue','random',7],['stack','stats',7],['bitset','buffer',6],['profiler','queue',2]]){if(!libs.querySelector('a[href$="/'+name+'.html"]')){const a=document.createElement('a');a.href=root+'libraries/'+name+'.html';const label=document.createElement('span');label.textContent=name;const n=document.createElement('small');n.textContent=String(count);a.append(label,n);libs.insertBefore(a,libs.querySelector('a[href$="/'+before+'.html"]'));}}
const LIBRARY_LEVELS=[{"en":"Beginner","es":"Principiante","names":["console","math","text","convert","random","datetime","arrays","collections","search","sort","validate","errors","files","path"]},{"en":"Intermediate","es":"Intermedio","names":["dictionary","buffer","stack","queue","sequences","stats","testing","time","json","colors","geometry","animation","vector","matrix","physics","canvas","sprite","camera","particles","image"]},{"en":"Advanced","es":"Avanzado","names":["binary","bits","bitset","encoding","checksum","compression","simd","memory","system","profiler","env","ui","game","events","network","http","https","discord"]}];
const LIBRARY_COUNTS={"console":3,"math":12,"text":9,"convert":8,"random":3,"datetime":7,"arrays":8,"collections":6,"search":4,"sort":4,"validate":6,"errors":7,"files":5,"path":6,"dictionary":8,"buffer":8,"stack":7,"queue":7,"sequences":4,"stats":6,"testing":4,"time":6,"json":15,"colors":8,"geometry":6,"animation":6,"vector":7,"matrix":6,"physics":5,"canvas":10,"sprite":6,"camera":4,"particles":6,"image":6,"binary":8,"bits":6,"bitset":6,"encoding":4,"checksum":3,"compression":3,"simd":1,"memory":4,"system":5,"profiler":2,"env":1,"ui":7,"game":7,"events":14,"network":3,"http":3,"https":1,"discord":34};

function libraryLearningOrder(){
 const groups=LIBRARY_LEVELS;
 const nameOf=a=>a.getAttribute('href')?.match(/\/?([^/]+)\.html(?:[?#].*)?$/)?.[1];
 function reorder(container,selector,kind){
  if(!container)return;
  const links=new Map([...container.querySelectorAll(selector)].map(a=>[nameOf(a),a]));
  const fragment=document.createDocumentFragment();
  groups.forEach((g,i)=>{
   const header=document.createElement(kind==='side'?'div':'h3');
   header.className=kind==='side'?'side-lib-level':'catalog-lib-level';
   header.dataset.es=g.es;header.textContent=g.en;header.dataset.level=String(i);fragment.append(header);
   for(const name of g.names){
    let a=links.get(name);
    if(!a&&kind==='side'){a=document.createElement('a');a.href=root+'libraries/'+name+'.html';const label=document.createElement('span'),n=document.createElement('small');label.textContent=name;a.append(label,n)}
    if(!a)continue;
    links.delete(name);a.dataset.level=String(i);
    const n=a.querySelector('small');if(n){if(kind==='side')n.textContent=String(LIBRARY_COUNTS[name]);else if(n.firstChild?.nodeType===3)n.firstChild.nodeValue=String(LIBRARY_COUNTS[name])+' '}
    if(kind==='catalog'&&typeof a.dataset.filter==='string'){a.dataset.filter+=' '+g.en+' '+g.es+' '+DOC_SEARCH.filter(x=>x.url.startsWith('libraries/'+name+'.html#')).map(x=>x.title).join(' ')}
    fragment.append(a)
   }
  });
  // Preserve future modules even before they receive a difficulty classification.
  for(const a of links.values())fragment.append(a);
  container.replaceChildren(fragment)
 }
 reorder(document.querySelector('.side-libs'),'a','side');
 reorder(document.querySelector('#library-grid'),'.library-card','catalog');
}
function refreshLevelHeadings(container){
 if(!container)return;
 for(const h of container.querySelectorAll('.side-lib-level,.catalog-lib-level'))h.hidden=![...container.querySelectorAll('a[data-level="'+h.dataset.level+'"]')].some(a=>!a.hidden)
}

libraryLearningOrder();
for(const a of side.querySelectorAll('nav a')){a.removeAttribute('aria-current');if(new URL(a.href,location.href).pathname===location.pathname)a.setAttribute('aria-current','page');}
const translate=(en,es)=>lang==='es'?es:en;
let labels=[], placeholders=[];
function registerLabels(){labels=$$('[data-es]').map(el=>({el,en:el.textContent,es:el.dataset.es}));placeholders=$$('[data-placeholder-es]').map(el=>({el,en:el.placeholder,es:el.dataset.placeholderEs}));}
function docsTokens(source,mode='tripol'){
 const keywords=new Set('show let const func return if else while for in repeat break continue assert and or not import struct try catch finally throw scratch'.split(' '));
 const types=new Set('int float bool string ints list string_list bool_list float_list'.split(' '));
 const builtins=new Set('input input_int len sum range abs min max sqrt text slice parse_int'.split(' '));
 const terminal=['cmd','sh','bash','shell','powershell','ps1'].includes(mode);
 const pattern=terminal?/(?:https?:\/\/[^\s"'<>]+|#[^\r\n]*|"(?:\\.|[^"\\\r\n])*"?|'(?:\\.|[^'\\\r\n])*'?|\$[\w:]+|--?[\w][\w-]*|\b[\w.-]+(?:[\/\\][\w./\\-]+)+|\b\d+(?:\.\d+)?\b|[A-Za-z_][A-Za-z_0-9.-]*|[=|&<>]+|\s+|.)/gu:/(?:\/\/[^\r\n]*|#[^\r\n]*|f?"(?:\\.|[^"\\\r\n])*"?|'(?:\\.|[^'\\\r\n])*'?|\b(?:0[xX][\da-fA-F]+|\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)\b|[A-Za-z_][A-Za-z_0-9]*|==|!=|<=|>=|=>|->|\+=|-=|\*=|\/=|%=|&&|\|\||[+\-*/%=<>!]|[{}()[\],.:;]|\s+|.)/gu;
 const out=[];const emit=(v,k='plain')=>{if(v)out.push({v,k})};
 for(const m of source.matchAll(pattern)){
  const v=m[0],after=source.slice(m.index+v.length);let k='plain';
  if(v.startsWith('#')||(!terminal&&v.startsWith('//')))k='comment';
  else if(!terminal&&v.startsWith('f"')){
   let start=0,i=2;
   while(i<v.length){
    if(v[i]==='\\'){i+=2;continue}
    if(v.slice(i,i+2)==='{{'||v.slice(i,i+2)==='}}'){i+=2;continue}
    if(v[i]==='{'){const end=v.indexOf('}',i+1);if(end<0)break;const field=v.slice(i+1,end);if(!field.includes('{')&&!field.includes('\\')&&!field.includes('"')){emit(v.slice(start,i),'string');emit('{','interpolation');out.push(...docsTokens(field,'tripol'));emit('}','interpolation');start=end+1;i=start;continue}}
    i++;
   }
   emit(v.slice(start),'string');continue;
  }
  else if(v.startsWith('"')||v.startsWith("'"))k='string';
  else if(/^\d/.test(v))k='number';
  else if(terminal){
   if(/^https?:\/\//.test(v))k='path';
   else if(v.startsWith('$')||/^[A-Z_][A-Z_0-9]+$/.test(v)&&after.startsWith('='))k='variable';
   else if(/^--?[\w]/.test(v))k='option';
   else if(/^(tripol|git|go|python|python3|cd|mkdir|cp|curl|node|rustc|cargo|npm|cmake|notepad|powershell|cmd|Read-Host|Get-ChildItem|Set-Location|echo|chmod|make)$/i.test(v))k='function';
   else if(/[\/\\]/.test(v))k='path';
   else if(/^[=|&<>]+$/.test(v))k='operator';
  }else{
   if(v==='true'||v==='false'||v==='null')k='literal';
   else if(keywords.has(v))k='keyword';
   else if(types.has(v))k='type';
   else if(builtins.has(v)||/^[A-Za-z_]/.test(v)&&/^\s*\(/.test(after))k='function';
   else if(v==='tripol'||v==='vault'||/^[A-Za-z_]/.test(v)&&/^\s*\./.test(after))k='namespace';
   else if(/^[+\-*/%=<>!&|]/.test(v))k='operator';
   else if(/^[{}()[\],.:;]$/.test(v))k='punct';
  }
  emit(v,k);
 }
 return out;
}
function codeMode(code){
 const pre=code.closest('pre');const explicit=[...code.classList,...(pre?[...pre.classList]:[])].find(c=>c.startsWith('language-'));
 if(explicit)return explicit.slice(9);
 if(pre?.classList.contains('signature'))return 'tripol';
 const s=code.textContent.trim();
 if(/^(?:tripol|git|go|python3?|cd|rustc|cargo|npm|cmake|curl|mkdir|cp|notepad|powershell)\s|^--?[\w-]|^\$[\w:]+|^[A-Z_][A-Z_0-9]+=/.test(s))return 'sh';
 if(/^(?:func|import|show|let|const|struct|if|for|while|try|scratch)\b|^[A-Za-z_]\w*\.[A-Za-z_]\w*|[=()[\]{}]/.test(s))return 'tripol';
 return pre?'text':'tripol';
}
function highlightDocs(){
 for(const code of [...document.querySelectorAll('.docs-article code, .docs-article pre:not(:has(code))')]){
  if(code.closest('.doc-live-panel'))continue;
  const raw=code.textContent,mode=codeMode(code);
  if(raw.length>100000||!raw||['text','output','plaintext'].includes(mode))continue;
  if(code.dataset.syntaxReady==='yes'&&code._tripolSource===raw&&code.querySelector('.doc-tok'))continue;
  if([...code.children].some(c=>!c.classList.contains('doc-tok')))continue;
  const frag=document.createDocumentFragment();
  for(const t of docsTokens(raw,mode)){if(t.k==='plain'){frag.append(document.createTextNode(t.v));continue}const span=document.createElement('span');span.className='doc-tok doc-tok-'+t.k;span.textContent=t.v;frag.append(span)}
  code.replaceChildren(frag);code.dataset.syntaxReady='yes';code._tripolSource=raw;
 }
}


// DOCS LIVE R1 — lazy editors, real compiler workers, no automatic execution.
const livePanels=[];let liveJob=null;
function liveElement(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function liveLabel(e,en,es){e.textContent=translate(en,es);e._liveLabel=[en,es];return e}
function liveButton(en,es,action,cls='doc-copy'){const b=liveLabel(liveElement('button',cls),en,es);b.type='button';b.addEventListener('click',action);return b}
function liveStatus(p,en,es,kind=''){p.message=[en,es];p.status.textContent=translate(en,es);p.status.dataset.state=kind}
function liveRefresh(){for(const e of $$('.doc-live-action,.doc-live-panel button,.doc-live-label,.doc-live-help'))if(e._liveLabel)e.textContent=translate(...e._liveLabel);for(const p of livePanels){if(p.message)p.status.textContent=translate(...p.message);p.input.placeholder=translate('One line per input()','Una línea por input()');p.editor.setAttribute('aria-label',translate('Editable TRIPOL example','Ejemplo TRIPOL editable'));p.input.setAttribute('aria-label',translate('Program input','Entrada del programa'));p.output.setAttribute('aria-label',translate('Program output','Salida del programa'))}}
function livePlayground(source){if(source.length>32768){toast(translate('Source exceeds 32 KiB','El código supera 32 KiB'));return}const u=new URL(root+'../playground/index.html',location.href);u.searchParams.set('lang',lang);u.hash='code='+encodeURIComponent(source);window.open(u.href,'_blank','noopener,noreferrer')}
function livePaint(p){const frag=document.createDocumentFragment();for(const t of docsTokens(p.editor.value)){if(t.k==='plain')frag.append(document.createTextNode(t.v));else{const el=liveElement('span','doc-tok doc-tok-'+t.k,t.v);frag.append(el)}}frag.append(document.createTextNode('\n'));p.highlight.replaceChildren(frag);p.stack.classList.add('painted');liveScroll(p)}
function liveScroll(p){p.highlight.scrollTop=p.editor.scrollTop;p.highlight.scrollLeft=p.editor.scrollLeft}
function liveStop(p,message=true){if(!liveJob||liveJob.panel!==p)return;const j=liveJob;liveJob=null;clearTimeout(j.timer);j.worker.terminate();p.run.disabled=false;p.stop.hidden=true;if(message)liveStatus(p,'Stopped','Detenido')}
function liveFiles(p,files=[]){
 p.files.replaceChildren();p.files.hidden=true;
 for(const file of files.slice(0,64)){
  if(typeof file.name!=='string'||!(file.bytes instanceof Uint8Array))continue;
  const row=liveElement('div','doc-live-file-row');row.append(liveElement('span','',file.name+' · '+file.bytes.length+' B'));
  row.append(liveButton('Download','Descargar',()=>{const u=URL.createObjectURL(new Blob([file.bytes],{type:file.name.endsWith('.wav')?'audio/wav':'application/octet-stream'}));const a=document.createElement('a');a.href=u;a.download=file.name.split('/').at(-1);a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}));p.files.append(row)
 }
 p.files.hidden=!p.files.children.length
}
function liveRun(p){liveFiles(p);
 if(liveJob)liveStop(liveJob.panel);
 const source=p.editor.value;
 if(new TextEncoder().encode(source).length>32768||new TextEncoder().encode(p.input.value).length>32768){liveStatus(p,'Input exceeds 32 KiB','La entrada supera 32 KiB','error');return}
 p.output.textContent='';p.run.disabled=true;p.stop.hidden=false;liveStatus(p,'Compiling with Web Engine R3…','Compilando con Web Engine R3…');
 let worker;try{worker=new Worker(new URL(root+'../playground/web-worker-r3.1.js',location.href))}catch(e){p.run.disabled=false;p.stop.hidden=true;liveStatus(p,'Compiler worker unavailable','Worker del compilador no disponible','error');p.output.textContent=String(e.message||e);return}
 const job={panel:p,worker,timer:null};liveJob=job;
 worker.onmessage=({data})=>{if(liveJob!==job)return;liveStop(p,false);p.output.textContent=(data.output||'')+(data.ok?'':'\n'+translate('Error: ','Error: ')+String(data.error||'Unknown error'));if(data.ok){if(Array.isArray(data.files))liveFiles(p,data.files);const time=Number(data.compileMs||0).toFixed(1)+' ms'+(data.build?' · '+data.build.slice(0,7):'');liveStatus(p,'WASM R3 · compiled in '+time,'WASM R3 · compilado en '+time,'ok')}else liveStatus(p,'Compiler/runtime diagnostic · no fallback','Diagnóstico del compilador/runtime · sin sustitución','error')};
 worker.onerror=()=>{if(liveJob!==job)return;liveStop(p,false);liveStatus(p,'Web Engine unavailable','Web Engine no disponible','error');p.output.textContent=translate('The compiler worker could not start. Open in Playground or try again.','No se pudo iniciar el compilador. Abre en Playground o vuelve a intentar.')};
 job.timer=setTimeout(()=>{if(liveJob!==job)return;liveStop(p,false);liveStatus(p,'Execution time limit (15 s)','Límite de ejecución (15 s)','error')},15000);
 try{worker.postMessage({source,input:p.input.value,compileOnly:false})}catch(e){liveStop(p,false);liveStatus(p,'Could not send source','No se pudo enviar el código','error');p.output.textContent=String(e.message||e)}
}
function makeLivePanel(source,original,trigger){
 const p={original,source};const panel=liveElement('section','doc-live-panel');p.panel=panel;panel.hidden=true;
 const toolbar=liveElement('div','doc-live-toolbar');const filename=liveElement('span','doc-live-file','example.tri');const actions=liveElement('div','doc-live-tools');toolbar.append(filename,actions);
 p.run=liveButton('▶ Run','▶ Ejecutar',()=>liveRun(p),'doc-live-run');
 p.stop=liveButton('Stop','Detener',()=>liveStop(p));p.stop.hidden=true;
 const reset=liveButton('Reset','Restaurar',()=>{liveStop(p,false);p.editor.value=p.original;p.input.value='';liveFiles(p);p.output.textContent='';livePaint(p);liveStatus(p,'Ready','Listo')});
 const open=liveButton('Playground ↗','Playground ↗',()=>livePlayground(p.editor.value));
 const close=liveButton('Close','Cerrar',()=>{liveStop(p);panel.hidden=true;source.hidden=false;trigger.setAttribute('aria-expanded','false');trigger.focus()});
 actions.append(p.run,p.stop,reset,open,close);
 p.stack=liveElement('div','doc-live-stack');p.highlight=liveElement('pre','doc-live-highlight');p.highlight.setAttribute('aria-hidden','true');p.editor=liveElement('textarea','doc-live-editor');p.editor.spellcheck=false;p.editor.autocapitalize='off';p.editor.setAttribute('autocorrect','off');p.editor.setAttribute('wrap','off');p.editor.maxLength=32768;p.editor.value=original;p.editor.setAttribute('aria-label',translate('Editable TRIPOL example','Ejemplo TRIPOL editable'));p.stack.append(p.highlight,p.editor);
 const inputBox=liveElement('details','doc-live-input');inputBox.append(liveLabel(liveElement('summary','doc-live-label'),'Optional input','Entrada opcional'));p.input=liveElement('textarea','doc-live-stdin');p.input.rows=2;p.input.maxLength=32768;inputBox.append(p.input);inputBox.open=/\binput(?:_int)?\s*\(/.test(original);
 const consoleBox=liveElement('div','doc-live-console');p.status=liveElement('div','doc-live-status');p.status.setAttribute('role','status');p.output=liveElement('pre','doc-live-output');p.output.setAttribute('aria-live','polite');p.files=liveElement('div','doc-live-files');p.files.hidden=true;consoleBox.append(p.status,p.output,p.files);
 const help=liveLabel(liveElement('p','doc-live-help'),'Runs with the real Web Engine R3. Unsupported browser features report a compiler error.','Ejecuta con Web Engine R3 real. Las funciones no compatibles muestran el error del compilador.');
 panel.append(toolbar,p.stack,inputBox,consoleBox,help);source.after(panel);livePanels.push(p);
 p.editor.addEventListener('input',()=>{livePaint(p);if(/\binput(?:_int)?\s*\(/.test(p.editor.value))inputBox.open=true});
 p.editor.addEventListener('scroll',()=>liveScroll(p));
 p.editor.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();liveRun(p)}else if(e.key==='Tab'&&!e.shiftKey){e.preventDefault();p.editor.setRangeText('    ',p.editor.selectionStart,p.editor.selectionEnd,'end');livePaint(p)}else if(e.key==='Escape'&&liveJob?.panel===p)liveStop(p)});
 liveStatus(p,'Ready · Ctrl + Enter','Listo · Ctrl + Enter');liveRefresh();
 return p
}
function installLive(source,host,original){
 if(!original||original.length>32768)return;
 let p;const button=liveButton('Try it','Probar',()=>{if(!p)p=makeLivePanel(source,original,button);if(!p.panel.hidden){liveStop(p);p.panel.hidden=true;source.hidden=false;button.setAttribute('aria-expanded','false');return}source.hidden=true;p.panel.hidden=false;button.setAttribute('aria-expanded','true');livePaint(p);p.editor.focus()},'doc-copy doc-live-action');
 button.setAttribute('aria-expanded','false');host.append(button)
}
function installAllLive(){
 for(const pre of $$('.docs-article pre')){
  // Function signatures and library implementation source are reference-only.
  if(pre.classList.contains('signature')||pre.closest('.function-card'))continue;
  if(document.querySelector('.doc-lib-guide[data-web-status="compiler-rejected"]'))continue;
  if(codeMode(pre.querySelector('code')||pre)!=='tripol')continue;
  const head=pre.closest('.code-shell')?.querySelector('.code-head');if(!head)continue;
  let actions=head.querySelector('.doc-code-actions');if(!actions){actions=liveElement('div','doc-code-actions');const copy=head.querySelector('.doc-copy');if(copy)actions.append(copy);head.append(actions)}
  installLive(pre,actions,pre.textContent);
 }
}
window.addEventListener('pagehide',()=>{if(liveJob)liveStop(liveJob.panel,false)});

function apply(){document.documentElement.lang=lang;labels.forEach(({el,en,es})=>el.textContent=translate(en,es));placeholders.forEach(({el,en,es})=>el.placeholder=translate(en,es));$('#doc-lang').textContent=lang==='en'?'ES':'EN';$('#doc-lang').setAttribute('aria-label',translate('Switch to Spanish','Cambiar a inglés'));try{localStorage.setItem('tripol-language',lang)}catch{};try{const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u.href)}catch{};localLinks();highlightDocs();liveRefresh();buildToc();if($('#doc-search').open)renderSearch();}
let timer;function toast(msg){const t=$('#doc-toast');t.textContent=msg;t.classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>t.classList.remove('visible'),1800)}
const LEARNING_GUIDES={"math.square":{"en":"Multiply a number by itself.","es":"Multiplica un número por sí mismo.","body":"show math.square(5)","out":"25"},"math.cube":{"en":"Multiply a number by itself three times.","es":"Multiplica un número por sí mismo tres veces.","body":"show math.cube(3)","out":"27"},"math.clamp":{"en":"Keep a number within two limits.","es":"Mantiene un número entre dos límites.","body":"show math.clamp(120, 0, 100)","out":"100","noteEn":"Use a lower limit no greater than the upper limit.","noteEs":"El límite inferior no debe superar el superior."},"math.power":{"en":"Raise an integer to a nonnegative exponent.","es":"Eleva un entero a un exponente no negativo.","body":"show math.power(2, 4)","out":"16"},"math.gcd":{"en":"Find the greatest common divisor of two integers.","es":"Calcula el máximo común divisor de dos enteros.","body":"show math.gcd(12, 18)","out":"6"},"math.root":{"en":"Calculate the square root of a nonnegative decimal.","es":"Calcula la raíz cuadrada de un decimal no negativo.","body":"show math.root(81.0)","out":"9.000000"},"math.pi":{"en":"Return the mathematical constant pi.","es":"Devuelve la constante matemática pi.","body":"show math.pi()","out":"3.141593"},"math.percent":{"en":"Calculate a percentage of a number.","es":"Calcula un porcentaje de un número.","body":"show math.percent(200.0, 10.0)","out":"20.000000"},"math.sqrt_value":{"en":"Calculate a square root, just like math.root.","es":"Calcula una raíz cuadrada, igual que math.root.","body":"show math.sqrt_value(25.0)","out":"5.000000"},"math.absolute":{"en":"Return the distance of an integer from zero.","es":"Devuelve la distancia de un entero respecto a cero.","body":"show math.absolute(-8)","out":"8"},"math.minimum":{"en":"Return the smaller integer.","es":"Devuelve el menor de dos enteros.","body":"show math.minimum(3, 8)","out":"3"},"math.maximum":{"en":"Return the larger integer.","es":"Devuelve el mayor de dos enteros.","body":"show math.maximum(3, 8)","out":"8"},"arrays.make":{"en":"Create an array filled with a single value.","es":"Crea un arreglo lleno del mismo valor.","body":"show arrays.make(3, 7)","out":"[7, 7, 7]"},"arrays.total":{"en":"Sum every integer in an array.","es":"Suma todos los enteros de un arreglo.","body":"a = [1, 2, 3]\nshow arrays.total(a)","out":"6"},"arrays.count":{"en":"Count occurrences of a value.","es":"Cuenta las apariciones de un valor.","body":"a = [2, 5, 2]\nshow arrays.count(a, 2)","out":"2"},"arrays.contains":{"en":"Check whether a value appears in an array.","es":"Comprueba si un valor aparece en un arreglo.","body":"a = [1, 2, 3]\nshow arrays.contains(a, 2)","out":"true"},"arrays.reversed":{"en":"Return a new array in reverse order.","es":"Devuelve un arreglo nuevo en orden inverso.","body":"a = [1, 2, 3]\nshow arrays.reversed(a)","out":"[3, 2, 1]"},"arrays.copy":{"en":"Create an independent copy of an array.","es":"Crea una copia independiente de un arreglo.","body":"a = [1, 2]\nb = arrays.copy(a)\nb[0] = 9\nshow a, b","out":"[1, 2] [9, 2]"},"arrays.length":{"en":"Count elements in an array.","es":"Cuenta los elementos de un arreglo.","body":"a = [10, 20, 30]\nshow arrays.length(a)","out":"3"},"arrays.copy_into":{"en":"Copy values into an existing dynamic array of equal length.","es":"Copia valores a un arreglo dinámico existente de igual longitud.","body":"source = [4, 7]\ndestination = ints(2)\nshow arrays.copy_into(destination, source)\nshow destination","out":"true\n[4, 7]","noteEn":"Returns false if lengths differ; the destination is unchanged.","noteEs":"Devuelve false si las longitudes difieren; el destino no cambia."},"collections.append":{"en":"Return a new array with an extra element at the end.","es":"Devuelve un arreglo nuevo con un elemento adicional al final.","body":"a = [1, 2]\nshow collections.append(a, 3)","out":"[1, 2, 3]","noteEn":"The original array is not modified.","noteEs":"El arreglo original no cambia."},"collections.concat":{"en":"Join two arrays into a new one.","es":"Une dos arreglos en uno nuevo.","body":"a = [1, 2]\nb = [3, 4]\nshow collections.concat(a, b)","out":"[1, 2, 3, 4]"},"collections.part":{"en":"Copy a range, including start but excluding end.","es":"Copia un intervalo, incluyendo start pero excluyendo end.","body":"a = [10, 20, 30, 40]\nshow collections.part(a, 1, 3)","out":"[20, 30]"},"collections.remove_at":{"en":"Copy an array without an indexed element.","es":"Copia un arreglo sin el elemento indicado.","body":"a = [10, 20, 30]\nshow collections.remove_at(a, 1)","out":"[10, 30]"},"collections.insert":{"en":"Make a new array with a value inserted at an index.","es":"Crea un arreglo nuevo insertando un valor en un índice.","body":"a = [10, 30]\nshow collections.insert(a, 1, 20)","out":"[10, 20, 30]"},"collections.equal":{"en":"Check whether two arrays contain the same ordered values.","es":"Comprueba si dos arreglos contienen los mismos valores en el mismo orden.","body":"a = [1, 2]\nb = [1, 2]\nshow collections.equal(a, b)","out":"true"},"text.size":{"en":"Count UTF-8 bytes, not necessarily visible characters.","es":"Cuenta bytes UTF-8, no necesariamente caracteres visibles.","body":"show text.size(\"TRIPOL\")","out":"6"},"text.empty":{"en":"Check whether a string is empty.","es":"Comprueba si una cadena está vacía.","body":"show text.empty(\"\")","out":"true"},"text.from_int":{"en":"Convert an integer to text.","es":"Convierte un entero en texto.","body":"show text.from_int(42)","out":"42"},"text.to_int":{"en":"Convert valid integer text into a number.","es":"Convierte texto entero válido en un número.","body":"show text.to_int(\"42\") + 1","out":"43"},"text.part":{"en":"Copy bytes from start (included) to end (excluded).","es":"Copia bytes desde start (incluido) hasta end (excluido).","body":"show text.part(\"TRIPOL\", 0, 3)","out":"TRI","noteEn":"UTF-8 characters may use several bytes.","noteEs":"Los caracteres UTF-8 pueden ocupar varios bytes."},"text.starts_with":{"en":"Check whether text begins with a prefix.","es":"Comprueba si un texto comienza por un prefijo.","body":"show text.starts_with(\"TRIPOL\", \"TRI\")","out":"true"},"text.ends_with":{"en":"Check whether text ends with a suffix.","es":"Comprueba si un texto termina con un sufijo.","body":"show text.ends_with(\"main.tri\", \".tri\")","out":"true"},"text.index_of":{"en":"Find the first byte index of a substring, or -1.","es":"Encuentra el primer índice por bytes de un fragmento, o -1.","body":"show text.index_of(\"TRIPOL\", \"POL\")","out":"3"},"text.contains":{"en":"Check whether text contains a substring.","es":"Comprueba si un texto contiene un fragmento.","body":"show text.contains(\"Hello TRIPOL\", \"TRIPOL\")","out":"true"},"datetime.leap":{"en":"Check whether a year has 366 days.","es":"Comprueba si un año es bisiesto y tiene 366 días.","body":"show datetime.leap(2024)","out":"true"},"datetime.days_in_month":{"en":"Count the days in a month and year.","es":"Devuelve cuántos días tiene un mes de un año concreto.","body":"show datetime.days_in_month(2024, 2)","out":"29"},"datetime.valid":{"en":"Check whether a date exists.","es":"Comprueba si una fecha es válida.","body":"show datetime.valid(2024, 2, 29)","out":"true"},"datetime.day_of_year":{"en":"Find the position of a day within its year.","es":"Devuelve la posición de un día dentro de su año.","body":"show datetime.day_of_year(2024, 2, 1)","out":"32"},"datetime.ordinal":{"en":"Return the day number counted from year 1.","es":"Devuelve el número de día contado desde el año 1.","body":"show datetime.ordinal(1, 1, 1)\nshow datetime.ordinal(1, 1, 2)","out":"1\n2","noteEn":"January 1 of year 1 is day 1; Gregorian years 1–9999.","noteEs":"El 1 de enero del año 1 es el día 1; años gregorianos de 1 a 9999."},"datetime.weekday":{"en":"Return a weekday number, with Monday = 1.","es":"Devuelve el número del día de la semana, con lunes = 1.","body":"show datetime.weekday(2024, 1, 1)","out":"1"},"datetime.days_between":{"en":"Calculate the signed difference in days between dates.","es":"Calcula la diferencia con signo en días entre fechas.","body":"show datetime.days_between(2024, 1, 1, 2024, 1, 3)","out":"2"},"json.quote":{"en":"Escape text and surround it with JSON quotes.","es":"Escapa un texto y lo rodea de comillas JSON.","body":"show json.quote(\"Hola \\\"TRIPOL\\\"\")","out":"\"Hola \\\"TRIPOL\\\"\"","noteEn":"Input must be valid UTF-8, at most 512 bytes.","noteEs":"La entrada debe ser UTF-8 válido, de hasta 512 bytes."},"json.integer":{"en":"Convert an integer to JSON numeric text.","es":"Convierte un entero en texto numérico JSON.","body":"show json.integer(-42)","out":"-42","noteEn":"","noteEs":""},"json.boolean":{"en":"Convert a boolean into JSON text.","es":"Convierte un booleano en texto JSON.","body":"show json.boolean(true)\nshow json.boolean(false)","out":"true\nfalse","noteEn":"","noteEs":""},"json.pair":{"en":"Create a JSON object containing one string property.","es":"Crea un objeto JSON con una propiedad de texto.","body":"show json.pair(\"name\", \"TRIPOL\")","out":"{\"name\":\"TRIPOL\"}","noteEn":"Both key and value are strings, not raw JSON values.","noteEs":"La clave y el valor son textos, no valores JSON sin procesar."},"json.integers":{"en":"Convert an integer array into JSON array text.","es":"Convierte un arreglo de enteros en texto de arreglo JSON.","body":"numbers = [1, 2, 3]\nshow json.integers(numbers)","out":"[1,2,3]","noteEn":"Maximum 128 integers.","noteEs":"Máximo 128 enteros."},"json.valid":{"en":"Check whether the entire string contains valid JSON.","es":"Comprueba si toda la cadena contiene JSON válido.","body":"show json.valid(\"{\\\"score\\\":100}\")\nshow json.valid(\"{score:100}\")","out":"true\nfalse","noteEn":"Maximum input 4096 bytes; nesting depth limited to 32.","noteEs":"Máximo 4096 bytes de entrada y profundidad 32."},"json.get_raw":{"en":"Read the original JSON text of a top-level property.","es":"Lee el texto JSON original de una propiedad del objeto principal.","body":"profile = \"{\\\"name\\\":\\\"TRIPOL\\\",\\\"score\\\":100}\"\nshow json.get_raw(profile, \"name\")\nshow json.get_raw(profile, \"score\")","out":"\"TRIPOL\"\n100","noteEn":"Maximum 4096 bytes. String values retain their quotes. Missing or invalid properties return empty text; this is not a general object decoder.","noteEs":"Máximo 4096 bytes. Los valores de texto conservan sus comillas. Las propiedades ausentes o inválidas devuelven texto vacío; no es un decodificador general."},"json.get_raw_large":{"en":"Read a top-level property from a larger JSON document.","es":"Lee una propiedad del objeto principal de un documento JSON más grande.","body":"event = \"{\\\"data\\\":{\\\"score\\\":100}}\"\nshow json.get_raw_large(event, \"data\")","out":"{\"score\":100}","noteEn":"Maximum 65535 input bytes and 512 key bytes. Returns raw JSON, not a decoded object.","noteEs":"Máximo 65535 bytes de entrada y 512 bytes de clave. Devuelve JSON sin procesar, no un objeto decodificado."},"encoding.hex_digit":{"en":"Convert 0–15 to one hexadecimal digit.","es":"Convierte un entero entre 0 y 15 en un dígito hexadecimal.","body":"show encoding.hex_digit(15)","out":"f"},"encoding.hex_byte":{"en":"Convert a byte to two hexadecimal digits.","es":"Convierte un byte en dos dígitos hexadecimales.","body":"show encoding.hex_byte(255)","out":"ff"},"encoding.hex_int":{"en":"Convert a nonnegative integer into hexadecimal text.","es":"Convierte un entero no negativo en texto hexadecimal.","body":"show encoding.hex_int(256)","out":"100"},"encoding.hex_text":{"en":"Encode UTF-8 bytes as hexadecimal text.","es":"Codifica los bytes UTF-8 en texto hexadecimal.","body":"show encoding.hex_text(\"Hi\")","out":"4869","noteEn":"Maximum 1024 input bytes.","noteEs":"Máximo 1024 bytes de entrada."},"simd.equal":{"en":"Compare lengths and contents of two integer arrays.","es":"Compara la longitud y el contenido de dos arreglos de enteros.","body":"a = [1, 2]\nb = [1, 2]\nshow simd.equal(a, b)","out":"true"},"discord.run":{"en":"Start the bot and keep it connected to Discord to answer registered commands.","es":"Inicia el bot y lo mantiene conectado a Discord para responder comandos registrados.","body":"discord.login_env()\ndiscord.status(\"online\")\ndiscord.activity(\"TRIPOL\")\ndiscord.reply(\"!hola\", \"Hola!\")\ndiscord.run()","out":null,"noteEn":"Native Windows. Set DISCORD_TOKEN, enable Message Content Intent, invite the bot and grant permissions. Type !hola in a permitted channel. Stop with Ctrl+C; automatic reconnect is not supported.","noteEs":"Windows nativo. Configura DISCORD_TOKEN, activa Message Content Intent, invita al bot y concede permisos. Escribe !hola en un canal permitido. Detén con Ctrl+C; no hay reconexión automática.","returns":["Returns 1 after the Gateway loop closes normally; failures may stop execution.","Devuelve 1 cuando el bucle Gateway termina normalmente; los fallos pueden detener la ejecución."]},"discord.send":{"en":"Send a message using the token stored in the local environment.","es":"Envía un mensaje usando el token configurado en el entorno local.","body":"show discord.send(\"YOUR_CHANNEL_ID\", \"Hola!\")","out":null,"noteEn":"Replace the channel ID and set DISCORD_TOKEN. Requires permission to send messages. Message: 1–512 UTF-8 bytes.","noteEs":"Sustituye el ID y configura DISCORD_TOKEN. Requiere permiso para enviar mensajes. Mensaje: 1–512 bytes UTF-8.","returns":["True if the request returns a nonempty response; network errors may stop execution.","true si la petición devuelve una respuesta no vacía; los fallos de red pueden detener el programa."]},"discord.login_env":{"en":"Load the bot token from DISCORD_TOKEN into private local configuration.","es":"Carga el token de DISCORD_TOKEN en la configuración privada local.","body":"show discord.login_env()","out":"true","noteEn":"Set a valid-format token locally before running. This does not open a network connection.","noteEs":"Configura localmente un token con formato válido. Esto no abre una conexión de red."},"discord.login":{"en":"Configure the bot using a token supplied to the function.","es":"Configura el bot utilizando un token recibido por la función.","body":"secret = discord.token()\nshow discord.login(secret)","out":"true","noteEn":"Set DISCORD_TOKEN locally. Prefer login_env() for everyday use; never hardcode secrets. Configuration does not validate the token with Discord.","noteEs":"Configura DISCORD_TOKEN localmente. Prefiere login_env() para uso habitual; nunca escribas secretos en el código. Configurar no valida el token con Discord."},"discord.reply":{"en":"Register or replace the response to an exact command.","es":"Registra o reemplaza la respuesta de un comando exacto.","body":"discord.reply(\"!hola\", \"Hola!\")\nshow discord.preview(\"!hola\")","out":"Hola!","noteEn":"Maximum 16 commands; command 1–128 bytes, response 1–512 bytes.","noteEs":"Máximo 16 comandos; comando de 1–128 bytes, respuesta de 1–512 bytes."},"discord.preview":{"en":"Look up a registered command response without sending a message.","es":"Consulta una respuesta registrada sin enviar un mensaje.","body":"discord.reply(\"!hola\", \"Hola!\")\nshow discord.preview(\"!hola\")","out":"Hola!","noteEn":"","noteEs":"","returns":["Response text or empty text if no command matches.","Texto de respuesta o texto vacío si ningún comando coincide."]},"discord.channel":{"en":"Select the channel filter for incoming Gateway commands and the destination for say().","es":"Selecciona el filtro de canal para comandos Gateway y el destino de say().","body":"show discord.channel(\"123\")\nshow discord.has_channel()","out":"true\ntrue","noteEn":"The example only configures a numeric ID; use a real channel ID when connecting.","noteEs":"El ejemplo solo configura un ID numérico; usa un ID real al conectarte."},"discord.say":{"en":"Send a message to the currently selected channel.","es":"Envía un mensaje al canal seleccionado.","body":"discord.login_env()\ndiscord.channel(\"YOUR_CHANNEL_ID\")\nshow discord.say(\"Hola!\")","out":null,"noteEn":"Requires login, a real channel ID and permission to send messages.","noteEs":"Requiere iniciar sesión, un ID real y permiso para enviar mensajes."},"discord.send_to":{"en":"Send a message to a specific channel using the configured token.","es":"Envía un mensaje a un canal concreto utilizando el token configurado.","body":"discord.login_env()\nshow discord.send_to(\"YOUR_CHANNEL_ID\", \"Hola!\")","out":null,"noteEn":"Replace the ID, configure DISCORD_TOKEN and grant the bot channel permissions.","noteEs":"Sustituye el ID, configura DISCORD_TOKEN y concede permisos al bot."},"discord.token":{"en":"Read DISCORD_TOKEN from the local environment.","es":"Lee DISCORD_TOKEN desde el entorno local.","body":"secret = discord.token()\nshow len(secret) > 0","out":"true","noteEn":"Set DISCORD_TOKEN locally. This example checks that a token exists without revealing it. Never print the token itself.","noteEs":"Configura DISCORD_TOKEN localmente. El ejemplo comprueba que existe sin revelarlo. Nunca imprimas el token.","returns":["Secret token; do not display it.","Token secreto; no lo muestres."]},"discord.identify_payload":{"en":"Build the Gateway identification JSON, including the private token.","es":"Construye el JSON de identificación del Gateway, que incluye el token privado.","body":"discord.login_env()\npayload = discord.identify_payload()\nshow len(payload) > 0","out":"true","noteEn":"Advanced helper. The payload contains the token: never print, log or share it. run() calls this internally.","noteEs":"Función avanzada. El resultado contiene el token: nunca lo imprimas, registres ni compartas. run() lo utiliza internamente."},"discord.configured":{"en":"Check whether a token has been stored in the local bot configuration.","es":"Comprueba si hay un token guardado en la configuración local.","body":"discord.reset()\nshow discord.configured()","out":"false","noteEn":"A true result does not guarantee the token is accepted by Discord.","noteEs":"Un resultado true no garantiza que Discord acepte el token."},"discord.welcome":{"en":"Set a message to send once the Gateway is ready.","es":"Configura un mensaje que se envía cuando el Gateway está listo.","body":"discord.channel(\"123\")\nshow discord.welcome(\"Bot listo!\")","out":"true","noteEn":"Maximum 512 bytes. Select a real channel before run(); empty text disables the greeting.","noteEs":"Máximo 512 bytes. Selecciona un canal real antes de run(); el texto vacío desactiva el saludo."},"discord.connected":{"en":"Check the local Gateway ready state.","es":"Comprueba si el Gateway está listo según su estado local.","body":"discord.reset()\nshow discord.connected()","out":"false","noteEn":"This is a local state check, not a fresh network test.","noteEs":"Comprueba el estado local, no realiza una prueba de red nueva."},"discord.gateway":{"en":"Discover the public Discord Gateway address without a bot token.","es":"Consulta la dirección pública del Gateway de Discord sin utilizar un token.","body":"show discord.gateway()","out":null,"noteEn":"Requires an Internet connection and native HTTPS support. The response is JSON.","noteEs":"Requiere conexión a Internet y HTTPS nativo. La respuesta es JSON.","returns":["JSON returned by Discord.","JSON devuelto por Discord."]},"discord.api_host":{"en":"Get the hostname used by the Discord API.","es":"Obtiene el nombre del servidor de la API de Discord.","body":"show discord.api_host()","out":"discord.com","noteEn":"","noteEs":""},"discord.channel_path":{"en":"Build the API path used to access messages in a channel.","es":"Construye la ruta de la API que permite acceder a los mensajes de un canal.","body":"show discord.channel_path(\"123\")","out":"/api/v10/channels/123/messages","noteEn":"The channel ID must contain 1–20 digits. This example does not contact Discord.","noteEs":"El ID debe contener entre 1 y 20 dígitos. Este ejemplo no contacta con Discord."},"discord.latest":{"en":"Fetch the newest message in a channel as JSON.","es":"Obtiene el mensaje más reciente de un canal como JSON.","body":"message = discord.latest(\"YOUR_CHANNEL_ID\")\nshow len(message) > 0","out":null,"noteEn":"Set DISCORD_TOKEN and replace the ID. The bot needs access to the channel and message history.","noteEs":"Configura DISCORD_TOKEN y sustituye el ID. El bot necesita acceso al canal y al historial.","returns":["Message JSON or empty text if no usable message is found.","JSON del mensaje o texto vacío si no se encuentra un mensaje utilizable."]},"discord.message_id":{"en":"Extract a numeric ID from a message JSON object.","es":"Extrae el ID numérico de un mensaje JSON.","body":"message = \"{\\\"id\\\":\\\"123\\\"}\"\nshow discord.message_id(message)","out":"123","noteEn":"Returns zero if the ID is absent, invalid or outside the integer range.","noteEs":"Devuelve cero si el ID falta, no es válido o está fuera del rango entero."},"discord.matches":{"en":"Check whether a message is an exact command from a non-bot, non-webhook author.","es":"Comprueba si un mensaje coincide exactamente con un comando y no procede de un bot ni webhook.","body":"message = \"{\\\"id\\\":\\\"123\\\",\\\"content\\\":\\\"!hola\\\",\\\"author\\\":{\\\"bot\\\":false}}\"\nshow discord.matches(message, \"!hola\")\nshow discord.matches(message, \"!adios\")","out":"true\nfalse","noteEn":"","noteEs":""},"discord.listen":{"en":"Start a legacy bot loop for one command in one channel.","es":"Inicia un bot antiguo que escucha un único comando en un canal.","body":"discord.listen(\"YOUR_CHANNEL_ID\", \"!hola\", \"Hola!\")","out":null,"noteEn":"Native Windows REST polling; needs DISCORD_TOKEN and channel permissions. Polls the latest message every 2500 ms; use run() for Gateway bots. Stop with Ctrl+C.","noteEs":"Sondeo REST en Windows nativo; requiere DISCORD_TOKEN y permisos. Consulta el último mensaje cada 2500 ms; usa run() para bots Gateway. Detén con Ctrl+C."},"discord.reset":{"en":"Clear the local bot configuration, including token, commands and channel.","es":"Borra la configuración local del bot, incluidos token, comandos y canal.","body":"discord.reply(\"!hola\", \"Hola!\")\nshow discord.reset()\nshow discord.preview(\"!hola\") == \"\"","out":"true\ntrue","noteEn":"Does not delete anything on Discord.","noteEs":"No elimina nada en Discord."},"discord.dispatch":{"en":"Find the registered response to a raw message JSON without making a network request.","es":"Busca la respuesta registrada para un mensaje JSON sin realizar peticiones de red.","body":"discord.reply(\"!hola\", \"Hola!\")\nmessage = \"{\\\"id\\\":\\\"123\\\",\\\"content\\\":\\\"!hola\\\",\\\"author\\\":{\\\"bot\\\":false}}\"\nshow discord.dispatch(message)","out":"Hola!","noteEn":"Bot and webhook messages are ignored.","noteEs":"Se ignoran mensajes de bots y webhooks."},"discord.has_channel":{"en":"Check whether a channel has been selected.","es":"Comprueba si hay un canal seleccionado.","body":"discord.channel(\"123\")\nshow discord.has_channel()","out":"true","noteEn":"","noteEs":""},"discord.all_channels":{"en":"Remove the channel filter so Gateway replies can work in permitted channels.","es":"Elimina el filtro para responder en canales permitidos mediante Gateway.","body":"discord.channel(\"123\")\nshow discord.all_channels()\nshow discord.has_channel()","out":"true\nfalse","noteEn":"say() and welcome messages still require a selected channel.","noteEs":"say() y los mensajes de bienvenida siguen necesitando un canal seleccionado."},"discord.parse_latest":{"en":"Extract the first message object from a JSON array returned by REST.","es":"Extrae el primer objeto de mensaje de un arreglo JSON devuelto por REST.","body":"result = \"[{\\\"id\\\":\\\"123\\\"},{\\\"id\\\":\\\"456\\\"}]\"\nshow discord.parse_latest(result)","out":"{\"id\":\"123\"}","noteEn":"","noteEs":"","returns":["First object as JSON or empty text on invalid input.","Primer objeto como JSON o texto vacío si la entrada no es válida."]},"discord.run_rest":{"en":"Start the legacy REST polling loop using the configured channel and commands.","es":"Inicia el bucle antiguo de sondeo REST con el canal y comandos configurados.","body":"discord.login_env()\ndiscord.channel(\"YOUR_CHANNEL_ID\")\ndiscord.reply(\"!hola\", \"Hola!\")\ndiscord.run_rest()","out":null,"noteEn":"Native Windows. Requires a selected channel, token and permissions. Polls the newest message; stop with Ctrl+C.","noteEs":"Windows nativo. Requiere canal, token y permisos. Consulta el último mensaje; detén con Ctrl+C."},"discord.setup":{"en":"Configure the token and channel in one call.","es":"Configura el token y el canal en una sola llamada.","body":"secret = discord.token()\nshow discord.setup(secret, \"123\")","out":"true","noteEn":"Configure DISCORD_TOKEN locally; replace 123 with the real ID for live use. No network connection is opened.","noteEs":"Configura DISCORD_TOKEN localmente; sustituye 123 por el ID real para conectarte. No abre una conexión."},"discord.status":{"en":"Choose the presence status sent when the bot identifies itself to Discord.","es":"Elige el estado de presencia que se envía al identificarse el bot.","body":"show discord.status(\"idle\")","out":"true","noteEn":"Allowed: online, idle, dnd, invisible. Configure before run().","noteEs":"Permitidos: online, idle, dnd, invisible. Configura antes de run()."},"discord.activity":{"en":"Choose the activity text displayed by the bot when connecting.","es":"Elige el texto de actividad que muestra el bot al conectarse.","body":"show discord.activity(\"Programando con TRIPOL\")","out":"true","noteEn":"Maximum 128 UTF-8 bytes; empty text clears the activity.","noteEs":"Máximo 128 bytes UTF-8; el texto vacío elimina la actividad."},"discord.ping":{"en":"Get the most recent Gateway heartbeat round-trip time in milliseconds.","es":"Obtiene la última latencia de heartbeat del Gateway en milisegundos.","body":"discord.reset()\nshow discord.ping()","out":"-1","noteEn":"Returns -1 until a heartbeat acknowledgement is recorded.","noteEs":"Devuelve -1 hasta que se registra una confirmación de heartbeat."},"discord.heartbeat_payload":{"en":"Build the JSON heartbeat for a Gateway sequence number.","es":"Construye el JSON de heartbeat para un número de secuencia.","body":"show discord.heartbeat_payload(7)\nshow discord.heartbeat_payload(-1)","out":"{\"op\":1,\"d\":7}\n{\"op\":1,\"d\":null}","noteEn":"Advanced protocol helper; run() sends heartbeats automatically.","noteEs":"Función avanzada del protocolo; run() envía heartbeats automáticamente."},"discord.event_channel":{"en":"Extract the channel ID of a MESSAGE_CREATE Gateway event and apply the channel filter.","es":"Extrae el ID de canal de un evento Gateway MESSAGE_CREATE y aplica el filtro de canal.","body":"event = \"{\\\"op\\\":0,\\\"t\\\":\\\"MESSAGE_CREATE\\\",\\\"d\\\":{\\\"channel_id\\\":\\\"123\\\",\\\"content\\\":\\\"!hola\\\",\\\"author\\\":{\\\"bot\\\":false}}}\"\nshow discord.event_channel(event)","out":"123","noteEn":"","noteEs":"","returns":["Channel ID text or empty text if the event is rejected.","ID de canal como texto o texto vacío si el evento se rechaza."]},"discord.gateway_reply":{"en":"Resolve a registered reply from a Gateway event without opening a connection.","es":"Busca la respuesta registrada para un evento Gateway sin abrir una conexión.","body":"discord.reply(\"!hola\", \"Hola!\")\nevent = \"{\\\"op\\\":0,\\\"t\\\":\\\"MESSAGE_CREATE\\\",\\\"d\\\":{\\\"channel_id\\\":\\\"123\\\",\\\"content\\\":\\\"!hola\\\",\\\"author\\\":{\\\"bot\\\":false}}}\"\nshow discord.gateway_reply(event)","out":"Hola!","noteEn":"Ignores bots, webhooks and events outside the configured channel filter.","noteEs":"Ignora bots, webhooks y eventos fuera del filtro de canal."},"json.ws":{"en":"Skip JSON whitespace from a byte offset.","es":"Salta los espacios en blanco JSON desde un índice de bytes.","body":"s = \"  42\"\nshow json.ws(s, 0, len(s))","out":"2","noteEn":"Advanced scanner helper; offsets start at zero and n is the exclusive end.","noteEs":"Función avanzada del analizador; los índices empiezan en cero y n es el límite exclusivo."},"json.hex":{"en":"Check whether a byte is an ASCII hexadecimal digit.","es":"Comprueba si un byte es un dígito hexadecimal ASCII.","body":"show json.hex(65)\nshow json.hex(71)","out":"true\nfalse","noteEn":"65 is A, 71 is G.","noteEs":"65 representa A y 71 representa G."},"json.digit":{"en":"Check whether a byte is an ASCII decimal digit.","es":"Comprueba si un byte es un dígito decimal ASCII.","body":"show json.digit(57)\nshow json.digit(65)","out":"true\nfalse","noteEn":"57 is 9, 65 is A.","noteEs":"57 representa 9 y 65 representa A."},"json.quoted":{"en":"Scan a JSON quoted string and return the byte offset immediately after it.","es":"Analiza una cadena JSON entre comillas y devuelve el índice de bytes justo después de ella.","body":"s = \"\\\"hola\\\"\"\nshow json.quoted(s, 0, len(s))","out":"6","noteEn":"Returns -1 if the string is invalid. Use quote() for creating strings.","noteEs":"Devuelve -1 si la cadena no es válida. Usa quote() para crear cadenas."},"json.literal":{"en":"Match a literal token at the current byte offset.","es":"Comprueba si un literal coincide desde el índice de bytes indicado.","body":"s = \"true\"\nshow json.literal(s, 0, len(s), \"true\")\nshow json.literal(s, 0, len(s), \"null\")","out":"4\n-1","noteEn":"Returns the offset after the match or -1. It does not validate a complete JSON document.","noteEs":"Devuelve el índice posterior a la coincidencia o -1. No valida un documento JSON completo."},"json.number":{"en":"Scan a JSON number and return where it ends, without converting it to a number.","es":"Analiza un número JSON y devuelve dónde termina, sin convertirlo a un número.","body":"s = \"-12.5\"\nshow json.number(s, 0, len(s))","out":"5","noteEn":"Returns -1 for invalid number syntax; use valid() to validate the complete input.","noteEs":"Devuelve -1 para sintaxis numérica inválida; usa valid() para validar toda la entrada."},"json.value":{"en":"Scan one JSON value (object, array, number, string, boolean or null).","es":"Analiza un valor JSON (objeto, arreglo, número, texto, booleano o null).","body":"s = \"[1,2]\"\nshow json.value(s, 0, len(s), 0)","out":"5","noteEn":"Advanced scanner; returns the next byte offset or -1. Nesting is limited to depth 32.","noteEs":"Analizador avanzado; devuelve el siguiente índice de bytes o -1. Profundidad máxima 32."},"animation.clamp01":{"en":"Limit a decimal to the range 0–1.","es":"Limita un decimal al intervalo de 0 a 1.","body":"show animation.clamp01(1.5)","out":"1.000000","noteEn":"","noteEs":""},"animation.linear":{"en":"Interpolate between two values with progress from 0 to 1.","es":"Interpola entre dos valores con un progreso de 0 a 1.","body":"show animation.linear(0.0, 10.0, 0.5)","out":"5.000000","noteEn":"","noteEs":""},"animation.ease_in":{"en":"Start an animation slowly and accelerate.","es":"Inicia una animación lentamente y acelera.","body":"show animation.ease_in(0.5)","out":"0.250000","noteEn":"","noteEs":""},"animation.ease_out":{"en":"Start quickly and slow down near the end.","es":"Comienza rápido y desacelera al final.","body":"show animation.ease_out(0.5)","out":"0.750000","noteEn":"","noteEs":""},"animation.smoothstep":{"en":"Smooth the beginning and end of a transition.","es":"Suaviza el inicio y el final de una transición.","body":"show animation.smoothstep(0.5)","out":"0.500000","noteEn":"","noteEs":""},"animation.frame":{"en":"Find the current looping frame from elapsed milliseconds.","es":"Calcula el fotograma actual de una animación repetitiva a partir de milisegundos.","body":"show animation.frame(250, 100, 4)","out":"2","noteEn":"Frame duration and count must be positive.","noteEs":"La duración y cantidad de fotogramas deben ser positivas."},"binary.is_byte":{"en":"Check if an integer fits in one byte.","es":"Comprueba si un entero cabe en un byte.","body":"show binary.is_byte(255)\nshow binary.is_byte(256)","out":"true\nfalse","noteEn":"","noteEs":""},"binary.valid":{"en":"Check whether all elements are bytes from 0 to 255.","es":"Comprueba si todos los elementos son bytes de 0 a 255.","body":"a = [0, 128, 255]\nshow binary.valid(a)","out":"true","noteEn":"","noteEs":""},"binary.read_u16_le":{"en":"Read a 16-bit unsigned number in little-endian order.","es":"Lee un entero sin signo de 16 bits en orden little-endian.","body":"a = [1, 2]\nshow binary.read_u16_le(a, 0)","out":"513","noteEn":"","noteEs":""},"binary.read_u32_le":{"en":"Read four bytes as a little-endian unsigned integer.","es":"Lee cuatro bytes como entero sin signo en orden little-endian.","body":"a = [1, 2, 0, 0]\nshow binary.read_u32_le(a, 0)","out":"513","noteEn":"","noteEs":""},"binary.u16_le":{"en":"Encode an unsigned 16-bit value with the least significant byte first.","es":"Codifica un entero sin signo de 16 bits con el byte menos significativo primero.","body":"show binary.u16_le(513)","out":"[1, 2]","noteEn":"","noteEs":""},"binary.u32_le":{"en":"Encode an unsigned 32-bit value into four little-endian bytes.","es":"Codifica un entero sin signo de 32 bits en cuatro bytes little-endian.","body":"show binary.u32_le(65536)","out":"[0, 0, 1, 0]","noteEn":"","noteEs":""},"binary.read_u16_be":{"en":"Read two bytes with the most significant byte first.","es":"Lee dos bytes con el byte más significativo primero.","body":"a = [2, 1]\nshow binary.read_u16_be(a, 0)","out":"513","noteEn":"","noteEs":""},"binary.u16_be":{"en":"Encode an unsigned 16-bit value in big-endian order.","es":"Codifica un entero sin signo de 16 bits en orden big-endian.","body":"show binary.u16_be(513)","out":"[2, 1]","noteEn":"","noteEs":""},"bits.mask":{"en":"Create a number with only one bit set.","es":"Crea un número con un único bit activado.","body":"show bits.mask(3)","out":"8","noteEn":"","noteEs":""},"bits.test":{"en":"Check whether a bit is set.","es":"Comprueba si un bit está activado.","body":"show bits.test(8, 3)","out":"true","noteEn":"","noteEs":""},"bits.set":{"en":"Turn on a bit without changing other bits.","es":"Activa un bit sin modificar los demás.","body":"show bits.set(1, 2)","out":"5","noteEn":"","noteEs":""},"bits.clear":{"en":"Turn off a bit.","es":"Desactiva un bit.","body":"show bits.clear(7, 1)","out":"5","noteEn":"","noteEs":""},"bits.toggle":{"en":"Reverse the state of a bit.","es":"Invierte el estado de un bit.","body":"show bits.toggle(5, 2)","out":"1","noteEn":"","noteEs":""},"bits.count":{"en":"Count the number of set bits.","es":"Cuenta los bits activados.","body":"show bits.count(7)","out":"3","noteEn":"","noteEs":""},"buffer.create":{"en":"Create an empty growable integer buffer with an initial capacity.","es":"Crea un búfer dinámico de enteros vacío con capacidad inicial.","body":"b = buffer.create(2)\nshow buffer.size(b)","out":"0","noteEn":"","noteEs":""},"buffer.capacity":{"en":"Return the number of storage positions currently allocated.","es":"Devuelve cuántas posiciones de almacenamiento están reservadas.","body":"b = buffer.create(4)\nshow buffer.capacity(b)","out":"4","noteEn":"","noteEs":""},"buffer.size":{"en":"Return the number of stored values.","es":"Devuelve cuántos valores contiene el búfer.","body":"b = buffer.create()\nb = buffer.push(b, 10)\nshow buffer.size(b)","out":"1","noteEn":"","noteEs":""},"buffer.push":{"en":"Append an integer and grow storage when necessary.","es":"Añade un entero y amplía el almacenamiento si hace falta.","body":"b = buffer.create(1)\nb = buffer.push(b, 10)\nb = buffer.push(b, 20)\nshow buffer.values(b)","out":"[10, 20]","noteEn":"Always reassign the returned buffer.","noteEs":"Reasigna siempre el búfer devuelto."},"buffer.get":{"en":"Read an element at a zero-based index.","es":"Lee un elemento por su índice, empezando en cero.","body":"b = buffer.create()\nb = buffer.push(b, 42)\nshow buffer.get(b, 0)","out":"42","noteEn":"","noteEs":""},"buffer.set":{"en":"Replace an existing element and return the new value.","es":"Reemplaza un elemento existente y devuelve el nuevo valor.","body":"b = buffer.create()\nb = buffer.push(b, 1)\nshow buffer.set(b, 0, 9)","out":"9","noteEn":"","noteEs":""},"buffer.pop":{"en":"Remove and return the last stored integer.","es":"Elimina y devuelve el último entero guardado.","body":"b = buffer.create()\nb = buffer.push(b, 7)\nshow buffer.pop(b)","out":"7","noteEn":"The buffer must not be empty.","noteEs":"El búfer no debe estar vacío."},"buffer.values":{"en":"Copy the logical contents into a new array.","es":"Copia el contenido lógico a un arreglo nuevo.","body":"b = buffer.create()\nb = buffer.push(b, 5)\nshow buffer.values(b)","out":"[5]","noteEn":"","noteEs":""},"camera.screen":{"en":"Convert a world coordinate to a screen coordinate.","es":"Convierte una coordenada del mundo en una de pantalla.","body":"show camera.screen(12, 2, 3)","out":"30","noteEn":"","noteEs":""},"camera.world":{"en":"Convert a screen coordinate back into world space using integer division.","es":"Convierte una coordenada de pantalla al mundo con división entera.","body":"show camera.world(30, 2, 3)","out":"12","noteEn":"","noteEs":""},"camera.follow":{"en":"Center a camera on a position while staying inside world bounds.","es":"Centra la cámara en una posición sin salir de los límites del mundo.","body":"show camera.follow(50, 20, 100)","out":"40","noteEn":"","noteEs":""},"camera.visible":{"en":"Check whether a rectangle overlaps the visible viewport.","es":"Comprueba si un rectángulo se cruza con el área visible.","body":"show camera.visible(5, 5, 10, 10, 100, 100)","out":"true","noteEn":"","noteEs":""},"canvas.size":{"en":"Calculate the number of pixels in a valid canvas.","es":"Calcula la cantidad de píxeles de un lienzo válido.","body":"show canvas.size(4, 3)","out":"12","noteEn":"","noteEs":""},"canvas.create":{"en":"Allocate a zero-filled RGB framebuffer.","es":"Reserva un arreglo de píxeles RGB inicializado en cero.","body":"p = canvas.create(2, 2)\nshow p","out":"[0, 0, 0, 0]","noteEn":"","noteEs":""},"canvas.clear":{"en":"Fill every pixel with a packed RGB color.","es":"Rellena todos los píxeles con un color RGB empaquetado.","body":"p = canvas.create(2, 2)\ncanvas.clear(p, 255)\nshow p","out":"[255, 255, 255, 255]","noteEn":"","noteEs":""},"canvas.pixel":{"en":"Write one pixel; return false if outside the canvas.","es":"Escribe un píxel; devuelve false si está fuera del lienzo.","body":"p = canvas.create(2, 2)\nshow canvas.pixel(p, 2, 2, 1, 0, 255)\nshow p","out":"true\n[0, 255, 0, 0]","noteEn":"","noteEs":""},"canvas.get":{"en":"Read the packed color at a pixel coordinate.","es":"Lee el color empaquetado de un píxel.","body":"p = canvas.create(2, 2)\ncanvas.pixel(p, 2, 2, 1, 1, 255)\nshow canvas.get(p, 2, 2, 1, 1)","out":"255","noteEn":"","noteEs":""},"canvas.rectangle":{"en":"Draw a filled rectangle clipped to the canvas.","es":"Dibuja un rectángulo relleno recortado a los límites del lienzo.","body":"p = canvas.create(3, 2)\nshow canvas.rectangle(p, 3, 2, 1, 0, 2, 1, 255)\nshow p","out":"2\n[0, 255, 255, 0, 0, 0]","noteEn":"","noteEs":""},"canvas.line":{"en":"Draw a line and return the number of pixels written.","es":"Dibuja una línea y devuelve cuántos píxeles escribió.","body":"p = canvas.create(3, 3)\nshow canvas.line(p, 3, 3, 0, 0, 2, 2, 255)","out":"3","noteEn":"","noteEs":""},"canvas.circle":{"en":"Draw a filled disk and return the number of visible pixels written.","es":"Dibuja un círculo relleno y devuelve cuántos píxeles visibles escribió.","body":"p = canvas.create(3, 3)\nshow canvas.circle(p, 3, 3, 1, 1, 1, 255)","out":"5","noteEn":"","noteEs":""},"canvas.blend":{"en":"Mix a color into one pixel using opacity from 0 to 100.","es":"Mezcla un color con un píxel usando opacidad de 0 a 100.","body":"p = canvas.create(1, 1)\nshow canvas.blend(p, 1, 1, 0, 0, 255, 50)\nshow p","out":"true\n[127]","noteEn":"","noteEs":""},"canvas.tile_map":{"en":"Draw visible palette-indexed tiles; tile zero is transparent.","es":"Dibuja mosaicos visibles mediante índices de paleta; el mosaico cero es transparente.","body":"p = canvas.create(2, 1)\ntiles = [0, 1]\npalette = [0, 255]\nshow canvas.tile_map(p, 2, 1, tiles, 2, 1, palette, 1, 0, 0)\nshow p","out":"1\n[0, 255]","noteEn":"","noteEs":""},"checksum.adler32":{"en":"Calculate the Adler-32 checksum of the UTF-8 bytes.","es":"Calcula la suma de comprobación Adler-32 de los bytes UTF-8.","body":"show checksum.adler32(\"abc\")","out":"38600999","noteEn":"","noteEs":""},"checksum.sum8":{"en":"Sum bytes modulo 256.","es":"Suma los bytes módulo 256.","body":"show checksum.sum8(\"abc\")","out":"38","noteEn":"","noteEs":""},"checksum.sum16":{"en":"Sum bytes modulo 65536.","es":"Suma los bytes módulo 65536.","body":"show checksum.sum16(\"abc\")","out":"294","noteEn":"","noteEs":""},"colors.rgb":{"en":"Pack red, green and blue channels into one RGB24 integer.","es":"Empaqueta los canales rojo, verde y azul en un entero RGB24.","body":"show colors.rgb(255, 0, 0)","out":"16711680","noteEn":"","noteEs":""},"colors.valid":{"en":"Check whether a number is a valid RGB24 color.","es":"Comprueba si un número representa un color RGB24 válido.","body":"show colors.valid(16777215)","out":"true","noteEn":"","noteEs":""},"colors.red":{"en":"Extract the red channel.","es":"Extrae el canal rojo.","body":"show colors.red(colors.rgb(10, 20, 30))","out":"10","noteEn":"","noteEs":""},"colors.green":{"en":"Extract the green channel.","es":"Extrae el canal verde.","body":"show colors.green(colors.rgb(10, 20, 30))","out":"20","noteEn":"","noteEs":""},"colors.blue":{"en":"Extract the blue channel.","es":"Extrae el canal azul.","body":"show colors.blue(colors.rgb(10, 20, 30))","out":"30","noteEn":"","noteEs":""},"colors.invert":{"en":"Invert all three RGB channels.","es":"Invierte los tres canales RGB.","body":"show colors.invert(0)","out":"16777215","noteEn":"","noteEs":""},"colors.gray":{"en":"Create a gray color with equal RGB channels.","es":"Crea un color gris con los tres canales iguales.","body":"show colors.gray(1)","out":"65793","noteEn":"","noteEs":""},"colors.mix":{"en":"Blend two colors using an integer percentage from 0 to 100.","es":"Mezcla dos colores usando un porcentaje entero de 0 a 100.","body":"show colors.mix(0, 255, 50)","out":"127","noteEn":"","noteEs":""},"compression.rle_encode":{"en":"Replace runs of equal integers with value/count pairs.","es":"Reemplaza secuencias de enteros iguales por parejas valor/cantidad.","body":"a = [7, 7, 7, 2]\nshow compression.rle_encode(a)","out":"[7, 3, 2, 1]","noteEn":"","noteEs":""},"compression.rle_valid":{"en":"Check whether RLE pairs can be safely decoded.","es":"Comprueba si las parejas RLE se pueden decodificar correctamente.","body":"a = [7, 3, 2, 1]\nshow compression.rle_valid(a)","out":"true","noteEn":"","noteEs":""},"compression.rle_decode":{"en":"Expand RLE value/count pairs into the original array.","es":"Expande las parejas RLE valor/cantidad al arreglo original.","body":"a = [7, 3, 2, 1]\nshow compression.rle_decode(a)","out":"[7, 7, 7, 2]","noteEn":"Decoded length is limited to 65535 integers.","noteEs":"La longitud decodificada se limita a 65535 enteros."},"console.ask":{"en":"Display a prompt and read a line of text.","es":"Muestra una pregunta y lee una línea de texto.","body":"name = console.ask(\"Name:\")\nshow name","out":null,"noteEn":"Enter Ada when prompted; output includes the prompt and Ada.","noteEs":"Introduce Ada cuando se solicite; la salida incluye la pregunta y Ada."},"console.ask_int":{"en":"Display a prompt and read an integer.","es":"Muestra una pregunta y lee un entero.","body":"age = console.ask_int(\"Age:\")\nshow age + 1","out":null,"noteEn":"Enter 16 to obtain 17 after the prompt.","noteEs":"Introduce 16 para obtener 17 después de la pregunta."},"console.line":{"en":"Print a line and return zero.","es":"Imprime una línea y devuelve cero.","body":"console.line(\"Hola TRIPOL\")","out":"Hola TRIPOL","noteEn":"","noteEs":""},"convert.celsius_to_fahrenheit":{"en":"Convert Celsius to Fahrenheit.","es":"Convierte grados Celsius a Fahrenheit.","body":"show convert.celsius_to_fahrenheit(20.0)","out":"68.000000","noteEn":"","noteEs":""},"convert.fahrenheit_to_celsius":{"en":"Convert Fahrenheit to Celsius.","es":"Convierte grados Fahrenheit a Celsius.","body":"show convert.fahrenheit_to_celsius(68.0)","out":"20.000000","noteEn":"","noteEs":""},"convert.km_to_miles":{"en":"Convert kilometers to miles.","es":"Convierte kilómetros a millas.","body":"show convert.km_to_miles(1.609344)","out":"1.000000","noteEn":"","noteEs":""},"convert.miles_to_km":{"en":"Convert miles to kilometers.","es":"Convierte millas a kilómetros.","body":"show convert.miles_to_km(1.0)","out":"1.609344","noteEn":"","noteEs":""},"convert.kg_to_lb":{"en":"Convert kilograms to pounds.","es":"Convierte kilogramos a libras.","body":"show convert.kg_to_lb(0.45359237)","out":"1.000000","noteEn":"","noteEs":""},"convert.lb_to_kg":{"en":"Convert pounds to kilograms.","es":"Convierte libras a kilogramos.","body":"show convert.lb_to_kg(1.0)","out":"0.453592","noteEn":"","noteEs":""},"convert.celsius_to_kelvin":{"en":"Convert Celsius to kelvin.","es":"Convierte grados Celsius a kelvin.","body":"show convert.celsius_to_kelvin(0.0)","out":"273.150000","noteEn":"","noteEs":""},"convert.kelvin_to_celsius":{"en":"Convert kelvin to Celsius.","es":"Convierte kelvin a grados Celsius.","body":"show convert.kelvin_to_celsius(273.15)","out":"0.000000","noteEn":"","noteEs":""},"dictionary.create":{"en":"Create a fixed-capacity map from text keys to integers.","es":"Crea un mapa de capacidad fija con claves de texto y valores enteros.","body":"d = dictionary.create(2)\nshow dictionary.size(d)","out":"0","noteEn":"","noteEs":""},"dictionary.capacity":{"en":"Return the maximum number of entries.","es":"Devuelve la cantidad máxima de entradas.","body":"d = dictionary.create(4)\nshow dictionary.capacity(d)","out":"4","noteEn":"","noteEs":""},"dictionary.locate":{"en":"Find the internal slot offset of a key, or -1.","es":"Busca el desplazamiento interno de una clave, o -1.","body":"d = dictionary.create(2)\nshow dictionary.locate(d, \"score\")","out":"-1","noteEn":"Prefer get() or contains() for everyday use.","noteEs":"Prefiere get() o contains() en el uso cotidiano."},"dictionary.contains":{"en":"Check if a key exists.","es":"Comprueba si existe una clave.","body":"d = dictionary.create(2)\ndictionary.set(d, \"score\", 42)\nshow dictionary.contains(d, \"score\")","out":"true","noteEn":"","noteEs":""},"dictionary.get":{"en":"Read an integer by key, returning a fallback if missing.","es":"Lee un entero por su clave, devolviendo un valor alternativo si falta.","body":"d = dictionary.create(2)\nshow dictionary.get(d, \"score\", -1)","out":"-1","noteEn":"","noteEs":""},"dictionary.size":{"en":"Count occupied entries.","es":"Cuenta las entradas ocupadas.","body":"d = dictionary.create(2)\ndictionary.set(d, \"score\", 42)\nshow dictionary.size(d)","out":"1","noteEn":"","noteEs":""},"dictionary.set":{"en":"Insert or update an integer; return false if full and the key is new.","es":"Inserta o actualiza un entero; devuelve false si está lleno y la clave es nueva.","body":"d = dictionary.create(2)\nshow dictionary.set(d, \"score\", 42)\nshow dictionary.get(d, \"score\")","out":"true\n42","noteEn":"Keys must contain 1–32 UTF-8 bytes.","noteEs":"Las claves deben tener entre 1 y 32 bytes UTF-8."},"dictionary.remove":{"en":"Remove an existing key; return false if absent.","es":"Elimina una clave existente; devuelve false si no existe.","body":"d = dictionary.create(2)\ndictionary.set(d, \"score\", 42)\nshow dictionary.remove(d, \"score\")\nshow dictionary.size(d)","out":"true\n0","noteEn":"","noteEs":""},"env.get":{"en":"Read a local process environment variable.","es":"Lee una variable del entorno del proceso local.","body":"show len(env.get(\"TRIPOL_DEMO\")) > 0","out":null,"noteEn":"Native Windows. Set TRIPOL_DEMO locally first; do not print secrets. Missing or oversized values return empty text.","noteEs":"Windows nativo. Configura TRIPOL_DEMO localmente; no imprimas secretos. Si falta o supera el límite, devuelve texto vacío."},"errors.is_int":{"en":"Check whether text represents a valid signed 64-bit integer.","es":"Comprueba si el texto representa un entero válido de 64 bits con signo.","body":"show errors.is_int(\"-42\")\nshow errors.is_int(\"abc\")","out":"true\nfalse","noteEn":"","noteEs":""},"errors.int_or":{"en":"Convert text to an integer or return a fallback.","es":"Convierte texto a entero o devuelve un valor alternativo.","body":"show errors.int_or(\"abc\", 7)","out":"7","noteEn":"","noteEs":""},"errors.can_divide":{"en":"Check whether integer division avoids zero and overflow.","es":"Comprueba si una división entera evita el cero y el desbordamiento.","body":"show errors.can_divide(10, 0)","out":"false","noteEn":"","noteEs":""},"errors.div_or":{"en":"Divide safely or return a fallback.","es":"Divide de forma segura o devuelve un valor alternativo.","body":"show errors.div_or(10, 0, -1)","out":"-1","noteEn":"","noteEs":""},"errors.get_or":{"en":"Read an array element or return a fallback for an invalid index.","es":"Lee un elemento o devuelve un valor alternativo si el índice no es válido.","body":"a = [10, 20]\nshow errors.get_or(a, 5, -1)","out":"-1","noteEn":"","noteEs":""},"errors.message":{"en":"Get the English description of an exception code.","es":"Obtiene la descripción en inglés de un código de excepción.","body":"show errors.message(11)","out":"Index out of bounds","noteEn":"","noteEs":""},"errors.message_es":{"en":"Get the Spanish description of an exception code.","es":"Obtiene la descripción en español de un código de excepción.","body":"show errors.message_es(11)","out":"Indice fuera de rango","noteEn":"","noteEs":""},"events.pressed":{"en":"Check whether a key is held in the focused game window.","es":"Comprueba si se mantiene pulsada una tecla en la ventana del juego.","body":"import tripol.game\n\ngame.window(\"Keys\", 320, 240)\nshow events.pressed(events.space())\ngame.close()","out":null,"noteEn":"Native Windows; the result depends on keyboard state.","noteEs":"Windows nativo; el resultado depende del teclado."},"events.left":{"en":"Return the key code for left arrow.","es":"Devuelve el código de la tecla flecha izquierda.","body":"show events.left()","out":"37","noteEn":"","noteEs":""},"events.right":{"en":"Return the key code for right arrow.","es":"Devuelve el código de la tecla flecha derecha.","body":"show events.right()","out":"39","noteEn":"","noteEs":""},"events.up":{"en":"Return the key code for up arrow.","es":"Devuelve el código de la tecla flecha arriba.","body":"show events.up()","out":"38","noteEn":"","noteEs":""},"events.down":{"en":"Return the key code for down arrow.","es":"Devuelve el código de la tecla flecha abajo.","body":"show events.down()","out":"40","noteEn":"","noteEs":""},"events.escape":{"en":"Return the key code for Escape.","es":"Devuelve el código de la tecla Escape.","body":"show events.escape()","out":"27","noteEn":"","noteEs":""},"events.space":{"en":"Return the key code for space bar.","es":"Devuelve el código de la tecla barra espaciadora.","body":"show events.space()","out":"32","noteEn":"","noteEs":""},"events.pad_connected":{"en":"Check whether a controller is connected.","es":"Comprueba si un mando está conectado.","body":"show events.pad_connected(0)","out":null,"noteEn":"Native Windows XInput; controller index 0–3.","noteEs":"XInput de Windows nativo; índice de mando de 0 a 3."},"events.pad_buttons":{"en":"Read the controller button bitmask.","es":"Lee la máscara de botones del mando.","body":"show events.pad_buttons(0)","out":null,"noteEn":"Native Windows XInput; value depends on the controller.","noteEs":"XInput de Windows nativo; depende del mando."},"events.pad_axis":{"en":"Read one of four stick axes.","es":"Lee uno de los cuatro ejes de los sticks.","body":"show events.pad_axis(0, 0)","out":null,"noteEn":"Native Windows XInput; axis and controller indexes 0–3.","noteEs":"XInput de Windows nativo; índices de eje y mando de 0 a 3."},"events.pad_trigger":{"en":"Read one of two controller triggers.","es":"Lee uno de los dos gatillos del mando.","body":"show events.pad_trigger(0, 0)","out":null,"noteEn":"Native Windows XInput; trigger 0–1, controller 0–3.","noteEs":"XInput de Windows nativo; gatillo 0–1, mando 0–3."},"events.mouse_x":{"en":"Read the horizontal mouse coordinate scaled to the logical width.","es":"Lee la coordenada horizontal del ratón adaptada al ancho lógico.","body":"import tripol.game\n\ngame.window(\"Mouse\", 320, 240)\nshow events.mouse_x(320)\ngame.close()","out":null,"noteEn":"Native Windows focused window; position varies.","noteEs":"Ventana enfocada de Windows nativo; posición variable."},"events.mouse_y":{"en":"Read the vertical mouse coordinate scaled to the logical height.","es":"Lee la coordenada vertical del ratón adaptada al alto lógico.","body":"import tripol.game\n\ngame.window(\"Mouse\", 320, 240)\nshow events.mouse_y(240)\ngame.close()","out":null,"noteEn":"Native Windows focused window; position varies.","noteEs":"Ventana enfocada de Windows nativo; posición variable."},"events.mouse_left":{"en":"Check whether the left mouse button is held.","es":"Comprueba si el botón izquierdo del ratón está pulsado.","body":"import tripol.game\n\ngame.window(\"Mouse\", 320, 240)\nshow events.mouse_left()\ngame.close()","out":null,"noteEn":"Native Windows focused window.","noteEs":"Ventana enfocada de Windows nativo."},"files.read":{"en":"Read text from a file.","es":"Lee texto de un archivo.","body":"files.write(\"demo.txt\", \"Hola\")\nshow files.read(\"demo.txt\")","out":"Hola","noteEn":"","noteEs":""},"files.write":{"en":"Write text, replacing previous content.","es":"Escribe texto, reemplazando el contenido anterior.","body":"files.write(\"demo.txt\", \"Hola\")\nshow files.read(\"demo.txt\")","out":"Hola","noteEn":"","noteEs":""},"files.append":{"en":"Add text at the end of a file.","es":"Añade texto al final de un archivo.","body":"files.write(\"demo.txt\", \"Hola\")\nfiles.append(\"demo.txt\", \" TRIPOL\")\nshow files.read(\"demo.txt\")","out":"Hola TRIPOL","noteEn":"","noteEs":""},"files.write_line":{"en":"Replace file contents with a line ending in a newline.","es":"Reemplaza el contenido con una línea terminada en salto de línea.","body":"files.write_line(\"demo.txt\", \"Hola\")\nshow len(files.read(\"demo.txt\"))","out":"5","noteEn":"","noteEs":""},"files.append_line":{"en":"Append a line ending in a newline.","es":"Añade una línea terminada en salto de línea.","body":"files.write_line(\"demo.txt\", \"Uno\")\nfiles.append_line(\"demo.txt\", \"Dos\")\nshow len(files.read(\"demo.txt\"))","out":"8","noteEn":"","noteEs":""},"game.window":{"en":"Open a native game window with a title and size.","es":"Abre una ventana nativa de juego con título y tamaño.","body":"show game.window(\"Demo\", 320, 240)\ngame.close()","out":null,"noteEn":"Native Windows. The title must be ASCII.","noteEs":"Windows nativo. El título debe ser ASCII."},"game.running":{"en":"Check whether the game window remains open.","es":"Comprueba si la ventana del juego sigue abierta.","body":"game.window(\"Demo\", 320, 240)\nshow game.running()\ngame.close()","out":null,"noteEn":"Requires the native Windows implementation.","noteEs":"Requiere la implementación nativa de Windows."},"game.present":{"en":"Display a packed RGB framebuffer in the window.","es":"Muestra un arreglo de píxeles RGB en la ventana.","body":"import tripol.canvas\n\ngame.window(\"Demo\", 320, 240)\np = canvas.create(320, 240)\ncanvas.clear(p, 255)\ngame.present(p, 320, 240)\ngame.wait(1000)\ngame.close()","out":null,"noteEn":"Native Windows; framebuffer size must match the dimensions.","noteEs":"Windows nativo; el tamaño de píxeles debe coincidir con las dimensiones."},"game.key":{"en":"Read a virtual-key code while the game has focus.","es":"Lee una tecla virtual mientras el juego tiene el foco.","body":"game.window(\"Demo\", 320, 240)\nshow game.key(32)\ngame.close()","out":null,"noteEn":"32 is the space bar; the result depends on input.","noteEs":"32 representa la barra espaciadora; el resultado depende de la entrada."},"game.close":{"en":"Close the current game window.","es":"Cierra la ventana actual del juego.","body":"game.window(\"Demo\", 320, 240)\nshow game.close()","out":null,"noteEn":"Requires the native Windows implementation.","noteEs":"Requiere la implementación nativa de Windows."},"game.wait":{"en":"Pause the game loop for a number of milliseconds.","es":"Pausa el bucle del juego durante varios milisegundos.","body":"game.wait(100)\nshow \"Ready\"","out":"Ready","noteEn":"Timing depends on the platform.","noteEs":"El tiempo depende de la plataforma."},"game.gl_frame":{"en":"Present experimental OpenGL triangles as x, y, RGB triples.","es":"Presenta triángulos OpenGL experimentales mediante grupos x, y, RGB.","body":"game.window(\"Demo\", 320, 240)\nvertices = [-500, -500, 16711680, 500, -500, 65280, 0, 500, 255]\nshow game.gl_frame(vertices)\ngame.wait(1000)\ngame.close()","out":null,"noteEn":"Native Windows WGL; coordinates -1000 to 1000. Do not mix presenters.","noteEs":"WGL de Windows nativo; coordenadas de -1000 a 1000. No mezcles presentadores."},"geometry.rectangle":{"en":"Calculate a rectangle's area.","es":"Calcula el área de un rectángulo.","body":"show geometry.rectangle(4.0, 3.0)","out":"12.000000","noteEn":"","noteEs":""},"geometry.circle":{"en":"Calculate the area of a circle.","es":"Calcula el área de un círculo.","body":"show geometry.circle(1.0)","out":"3.141593","noteEn":"","noteEs":""},"geometry.circumference":{"en":"Calculate the perimeter of a circle.","es":"Calcula el perímetro de un círculo.","body":"show geometry.circumference(1.0)","out":"6.283185","noteEn":"","noteEs":""},"geometry.triangle":{"en":"Calculate triangle area from base and height.","es":"Calcula el área de un triángulo a partir de base y altura.","body":"show geometry.triangle(6.0, 4.0)","out":"12.000000","noteEn":"","noteEs":""},"geometry.distance":{"en":"Calculate Euclidean distance between two 2D points.","es":"Calcula la distancia euclidiana entre dos puntos 2D.","body":"show geometry.distance(0.0, 0.0, 3.0, 4.0)","out":"5.000000","noteEn":"","noteEs":""},"geometry.lerp":{"en":"Interpolate or extrapolate between two values.","es":"Interpola o extrapola entre dos valores.","body":"show geometry.lerp(10.0, 20.0, 0.5)","out":"15.000000","noteEn":"Unlike animation.linear, t is not clamped.","noteEs":"A diferencia de animation.linear, t no se limita."},"http.get_raw":{"en":"Send a plain HTTP/1.0 GET and return headers and body.","es":"Envía una petición GET HTTP/1.0 sin cifrado y devuelve cabeceras y cuerpo.","body":"import tripol.network\n\nresponse = http.get_raw(network.loopback(), 8080, \"localhost\", \"/\")\nshow http.status(response)","out":null,"noteEn":"Requires a local HTTP server on port 8080 and native TCP support. No TLS; never send secrets.","noteEs":"Requiere un servidor HTTP local en el puerto 8080 y TCP nativo. Sin TLS; nunca envíes secretos."},"http.status":{"en":"Extract the HTTP status code from a raw response.","es":"Extrae el código de estado HTTP de una respuesta sin procesar.","body":"show http.status(\"HTTP/1.0 200 OK\")","out":"200","noteEn":"","noteEs":""},"http.body":{"en":"Extract the text after the header separator.","es":"Extrae el texto después del separador de cabeceras.","body":"response = \"HTTP/1.0 200 OK\\r\\n\\r\\nHola\"\nshow http.body(response)","out":"Hola","noteEn":"Does not decode chunked transfer encoding.","noteEs":"No decodifica transferencias por fragmentos."},"https.get":{"en":"Request the text body of a successful HTTPS GET.","es":"Solicita el cuerpo de texto de una petición HTTPS GET exitosa.","body":"response = https.get(\"example.com\", \"/\")\nshow len(response) > 0","out":null,"noteEn":"Native Windows WinHTTP; uses OS certificate trust, no redirects. Requires Internet.","noteEs":"WinHTTP de Windows nativo; utiliza certificados del sistema, sin redirecciones. Requiere Internet."},"image.flip_x":{"en":"Return a horizontally mirrored image.","es":"Devuelve una imagen reflejada horizontalmente.","body":"p = [1, 2, 3, 4]\nshow image.flip_x(p, 2, 2)","out":"[2, 1, 4, 3]","noteEn":"","noteEs":""},"image.flip_y":{"en":"Return a vertically mirrored image.","es":"Devuelve una imagen reflejada verticalmente.","body":"p = [1, 2, 3, 4]\nshow image.flip_y(p, 2, 2)","out":"[3, 4, 1, 2]","noteEn":"","noteEs":""},"image.crop":{"en":"Copy a rectangular area into an independent image.","es":"Copia un área rectangular a una imagen independiente.","body":"p = [1, 2, 3, 4]\nshow image.crop(p, 2, 2, 1, 0, 1, 2)","out":"[2, 4]","noteEn":"","noteEs":""},"image.grayscale":{"en":"Convert RGB pixels to grayscale using weighted channels.","es":"Convierte píxeles RGB a escala de grises ponderando los canales.","body":"p = [0, 16777215]\nshow image.grayscale(p)","out":"[0, 16777215]","noteEn":"","noteEs":""},"image.ppm":{"en":"Encode a small RGB image in ASCII PPM (P3) format.","es":"Codifica una imagen RGB pequeña en formato PPM ASCII (P3).","body":"p = [16711680]\nshow image.ppm(p, 1, 1)","out":null,"noteEn":"At most 256 pixels; not PNG or JPEG.","noteEs":"Máximo 256 píxeles; no es PNG ni JPEG."},"image.save_ppm":{"en":"Save a small image as an ASCII PPM file.","es":"Guarda una imagen pequeña como archivo PPM ASCII.","body":"p = [16711680]\nshow image.save_ppm(\"demo.ppm\", p, 1, 1) > 0","out":"true","noteEn":"Requires file output support. At most 256 pixels.","noteEs":"Requiere soporte de archivos. Máximo 256 píxeles."},"matrix.size":{"en":"Calculate the number of elements in a valid matrix shape.","es":"Calcula cuántos elementos tiene una matriz de dimensiones válidas.","body":"show matrix.size(2, 3)","out":"6","noteEn":"","noteEs":""},"matrix.zeros":{"en":"Create a flat zero-filled integer matrix.","es":"Crea una matriz plana de enteros llena de ceros.","body":"show matrix.zeros(2, 2)","out":"[0, 0, 0, 0]","noteEn":"","noteEs":""},"matrix.identity":{"en":"Create a square identity matrix in row-major order.","es":"Crea una matriz identidad cuadrada ordenada por filas.","body":"show matrix.identity(2)","out":"[1, 0, 0, 1]","noteEn":"","noteEs":""},"matrix.transpose":{"en":"Swap rows and columns of a flat matrix.","es":"Intercambia filas y columnas de una matriz plana.","body":"a = [1, 2, 3, 4, 5, 6]\nshow matrix.transpose(a, 2, 3)","out":"[1, 4, 2, 5, 3, 6]","noteEn":"","noteEs":""},"matrix.add":{"en":"Add matching elements of two equally sized matrices.","es":"Suma elementos correspondientes de dos matrices de igual tamaño.","body":"a = [1, 2]\nb = [3, 4]\nshow matrix.add(a, b)","out":"[4, 6]","noteEn":"","noteEs":""},"matrix.dot":{"en":"Calculate the dot product of two integer vectors.","es":"Calcula el producto escalar de dos vectores enteros.","body":"a = [1, 2]\nb = [3, 4]\nshow matrix.dot(a, b)","out":"11","noteEn":"","noteEs":""},"memory.capacity":{"en":"Report the target's arena capacity in bytes.","es":"Informa la capacidad de la arena de memoria del destino en bytes.","body":"show memory.capacity()","out":null,"noteEn":"Native and browser limits differ; this is not total RAM.","noteEs":"Los límites nativos y web difieren; no es la RAM total."},"memory.used":{"en":"Report the currently charged arena bytes.","es":"Informa los bytes de arena actualmente utilizados.","body":"a = ints(10)\nshow memory.used()","out":null,"noteEn":"","noteEs":""},"memory.committed":{"en":"Report committed arena bytes, according to the target.","es":"Informa los bytes comprometidos de la arena según el destino.","body":"show memory.committed()","out":null,"noteEn":"Web reports logical charged bytes, not process memory.","noteEs":"La web informa bytes lógicos, no memoria del proceso."},"memory.available":{"en":"Report arena capacity minus usage.","es":"Informa la capacidad de arena menos su uso.","body":"show memory.available()","out":null,"noteEn":"","noteEs":""},"network.ipv4":{"en":"Pack four IPv4 octets into an unsigned 32-bit integer.","es":"Empaqueta cuatro octetos IPv4 en un entero de 32 bits sin signo.","body":"show network.ipv4(127, 0, 0, 1)","out":"2130706433","noteEn":"","noteEs":""},"network.exchange":{"en":"Send a TCP request and read text until the peer closes.","es":"Envía una petición TCP y lee texto hasta que el otro extremo cierra.","body":"response = network.exchange(network.loopback(), 8080, \"hello\")\nshow response","out":null,"noteEn":"Requires a local TCP test server on port 8080 and native sockets; no raw TCP in browsers.","noteEs":"Requiere un servidor TCP local de prueba en el puerto 8080 y sockets nativos; no hay TCP directo en navegadores."},"network.loopback":{"en":"Return the packed address 127.0.0.1.","es":"Devuelve la dirección empaquetada 127.0.0.1.","body":"show network.loopback()","out":"2130706433","noteEn":"","noteEs":""},"particles.create":{"en":"Allocate a pool of particles with zero life.","es":"Reserva un grupo de partículas con vida inicial cero.","body":"p = particles.create(3)\nshow particles.count(p)","out":"3","noteEn":"","noteEs":""},"particles.count":{"en":"Return the total number of particle slots.","es":"Devuelve el total de espacios para partículas.","body":"p = particles.create(3)\nshow particles.count(p)","out":"3","noteEn":"","noteEs":""},"particles.step":{"en":"Advance positions and reduce life by one tick; count survivors.","es":"Avanza las posiciones y reduce la vida un tick; cuenta las supervivientes.","body":"p = particles.create(2)\nparticles.burst(p, 5, 5, 1)\nshow particles.step(p)","out":"0","noteEn":"","noteEs":""},"particles.alive":{"en":"Count particles whose life is positive.","es":"Cuenta las partículas cuya vida es positiva.","body":"p = particles.create(3)\nparticles.burst(p, 5, 5)\nshow particles.alive(p)","out":"3","noteEn":"","noteEs":""},"particles.burst":{"en":"Reset the pool into a deterministic burst at a position.","es":"Reinicia el grupo como una explosión determinista en una posición.","body":"p = particles.create(3)\nshow particles.burst(p, 10, 10, 4)","out":"3","noteEn":"","noteEs":""},"particles.draw":{"en":"Draw living particles into a clipped RGB framebuffer.","es":"Dibuja partículas vivas dentro de un arreglo RGB recortado.","body":"import tripol.canvas\n\np = particles.create(1)\nparticles.burst(p, 1, 1)\nframe = canvas.create(3, 3)\nshow particles.draw(p, frame, 3, 3, 0, 0, 255)","out":"1","noteEn":"","noteEs":""},"path.separator":{"en":"Check whether a byte is a slash or backslash.","es":"Comprueba si un byte representa una barra normal o invertida.","body":"show path.separator(47)\nshow path.separator(92)","out":"true\ntrue","noteEn":"","noteEs":""},"path.last_separator":{"en":"Find the final separator's byte index, or -1.","es":"Busca el índice por bytes del último separador, o -1.","body":"show path.last_separator(\"a/b.txt\")","out":"1","noteEn":"","noteEs":""},"path.basename":{"en":"Return the last path component.","es":"Devuelve el último componente de una ruta.","body":"show path.basename(\"docs/main.tri\")","out":"main.tri","noteEn":"","noteEs":""},"path.dirname":{"en":"Return the path before the last separator.","es":"Devuelve la ruta anterior al último separador.","body":"show path.dirname(\"docs/main.tri\")","out":"docs","noteEn":"","noteEs":""},"path.extension":{"en":"Return the last filename extension, including its dot.","es":"Devuelve la última extensión del nombre, incluyendo el punto.","body":"show path.extension(\"main.tri\")","out":".tri","noteEn":"","noteEs":""},"path.join":{"en":"Join path text with a slash when needed.","es":"Une textos de ruta con una barra cuando hace falta.","body":"show path.join(\"docs\", \"main.tri\")","out":"docs/main.tri","noteEn":"Lexical only: does not resolve traversal or check the filesystem.","noteEs":"Solo manipula texto: no resuelve rutas relativas ni comprueba el sistema de archivos."},"physics.overlap":{"en":"Check if two axis-aligned rectangles overlap with positive area.","es":"Comprueba si dos rectángulos alineados a los ejes se superponen con área positiva.","body":"show physics.overlap(0, 0, 10, 10, 5, 5, 10, 10)","out":"true","noteEn":"","noteEs":""},"physics.contains":{"en":"Check whether a point is inside a rectangle.","es":"Comprueba si un punto está dentro de un rectángulo.","body":"show physics.contains(0, 0, 10, 10, 5, 5)","out":"true","noteEn":"","noteEs":""},"physics.clamp_position":{"en":"Keep an object of a given extent inside a movement limit.","es":"Mantiene un objeto de tamaño dado dentro de un límite de movimiento.","body":"show physics.clamp_position(95, 10, 100)","out":"90","noteEn":"","noteEs":""},"physics.integrate":{"en":"Advance a position at constant velocity for a time step.","es":"Avanza una posición con velocidad constante durante un intervalo.","body":"show physics.integrate(0.0, 10.0, 2.0)","out":"20.000000","noteEn":"","noteEs":""},"physics.gravity":{"en":"Update velocity using acceleration and a time step.","es":"Actualiza la velocidad usando aceleración y un intervalo de tiempo.","body":"show physics.gravity(0.0, 9.8, 1.0)","out":"9.800000","noteEn":"","noteEs":""},"random.next":{"en":"Advance the deterministic pseudorandom seed.","es":"Avanza la semilla pseudoaleatoria determinista.","body":"show random.next(1)","out":"48271","noteEn":"Not cryptographically secure; seed must be 1–2147483646.","noteEs":"No es criptográficamente seguro; semilla de 1 a 2147483646."},"random.unit":{"en":"Generate a deterministic decimal between zero and one.","es":"Genera un decimal determinista entre cero y uno.","body":"show random.unit(1) > 0.0","out":"true","noteEn":"","noteEs":""},"random.bounded":{"en":"Generate a deterministic integer from 0 to limit-1.","es":"Genera un entero determinista desde 0 hasta limit-1.","body":"show random.bounded(1, 10)","out":"0","noteEn":"","noteEs":""},"search.linear":{"en":"Find the first occurrence of a value, or -1.","es":"Busca la primera aparición de un valor, o -1.","body":"a = [8, 3, 8]\nshow search.linear(a, 8)","out":"0","noteEn":"","noteEs":""},"search.lower_bound":{"en":"Find the insertion index in an ascending sorted array.","es":"Busca el índice de inserción en un arreglo ordenado ascendentemente.","body":"a = [1, 3, 5]\nshow search.lower_bound(a, 4)","out":"2","noteEn":"","noteEs":""},"search.binary":{"en":"Find a value in an ascending sorted array, or -1.","es":"Busca un valor en un arreglo ordenado ascendentemente, o -1.","body":"a = [1, 3, 5]\nshow search.binary(a, 5)","out":"2","noteEn":"","noteEs":""},"search.last":{"en":"Find the last occurrence of a value, or -1.","es":"Busca la última aparición de un valor, o -1.","body":"a = [8, 3, 8]\nshow search.last(a, 8)","out":"2","noteEn":"","noteEs":""},"sequences.arithmetic":{"en":"Create a sequence by adding a constant step.","es":"Crea una secuencia sumando un paso constante.","body":"show sequences.arithmetic(4, 2, 3)","out":"[2, 5, 8, 11]","noteEn":"","noteEs":""},"sequences.fibonacci":{"en":"Create the first n Fibonacci numbers, beginning at zero.","es":"Crea los primeros n números de Fibonacci empezando por cero.","body":"show sequences.fibonacci(7)","out":"[0, 1, 1, 2, 3, 5, 8]","noteEn":"","noteEs":""},"sequences.factorial":{"en":"Calculate n factorial for integers from 0 to 20.","es":"Calcula el factorial de un entero de 0 a 20.","body":"show sequences.factorial(5)","out":"120","noteEn":"","noteEs":""},"sequences.triangular":{"en":"Calculate the sum of integers from 1 to n.","es":"Calcula la suma de enteros desde 1 hasta n.","body":"show sequences.triangular(5)","out":"15","noteEn":"","noteEs":""},"sort.sift":{"en":"Restore the max-heap property below a selected root in a dynamic array.","es":"Restaura la propiedad de montículo máximo bajo una raíz en un arreglo dinámico.","body":"a = ints(3)\na[0] = 1\na[1] = 3\na[2] = 2\nsort.sift(a, 0, 3)\nshow a","out":"[3, 1, 2]","noteEn":"Advanced helper; use ascending() for ordinary sorting.","noteEs":"Función avanzada; usa ascending() para ordenar normalmente."},"sort.ascending":{"en":"Return a sorted copy from smallest to largest.","es":"Devuelve una copia ordenada de menor a mayor.","body":"a = [3, 1, 2]\nshow sort.ascending(a)","out":"[1, 2, 3]","noteEn":"","noteEs":""},"sort.descending":{"en":"Return a sorted copy from largest to smallest.","es":"Devuelve una copia ordenada de mayor a menor.","body":"a = [3, 1, 2]\nshow sort.descending(a)","out":"[3, 2, 1]","noteEn":"","noteEs":""},"sort.sorted":{"en":"Check whether an array is sorted in ascending order.","es":"Comprueba si un arreglo está ordenado ascendentemente.","body":"a = [1, 2, 3]\nshow sort.sorted(a)","out":"true","noteEn":"","noteEs":""},"sprite.draw_key":{"en":"Draw a sprite while skipping pixels matching a transparent color key.","es":"Dibuja un sprite omitiendo los píxeles que coinciden con el color transparente.","body":"dst = ints(2)\nsrc = [0, 255]\nshow sprite.draw_key(dst, 2, 1, src, 2, 1, 0, 0, 0)\nshow dst","out":"1\n[0, 255]","noteEn":"","noteEs":""},"sprite.draw":{"en":"Copy visible sprite pixels into a destination framebuffer.","es":"Copia píxeles visibles de un sprite al arreglo de destino.","body":"dst = ints(2)\nsrc = [255]\nshow sprite.draw(dst, 2, 1, src, 1, 1, 1, 0)\nshow dst","out":"1\n[0, 255]","noteEn":"","noteEs":""},"sprite.solid":{"en":"Create a rectangular sprite of one color.","es":"Crea un sprite rectangular de un único color.","body":"show sprite.solid(2, 1, 255)","out":"[255, 255]","noteEn":"","noteEs":""},"sprite.rotate90":{"en":"Rotate a sprite clockwise by 90 degrees.","es":"Gira un sprite 90 grados en sentido horario.","body":"src = [1, 2, 3, 4]\nshow sprite.rotate90(src, 2, 2)","out":"[3, 1, 4, 2]","noteEn":"","noteEs":""},"sprite.scale_nearest":{"en":"Resize using nearest-neighbor sampling.","es":"Cambia el tamaño usando vecino más cercano.","body":"src = [1, 2]\nshow sprite.scale_nearest(src, 2, 1, 4, 1)","out":"[1, 1, 2, 2]","noteEn":"","noteEs":""},"sprite.draw_scaled":{"en":"Draw a scaled sprite with clipping, optional color key and opacity.","es":"Dibuja un sprite escalado con recorte, color transparente opcional y opacidad.","body":"dst = ints(2)\nsrc = [255]\nshow sprite.draw_scaled(dst, 2, 1, src, 1, 1, 0, 0, 2, 1)\nshow dst","out":"2\n[255, 255]","noteEn":"","noteEs":""},"stats.mean":{"en":"Calculate the arithmetic average of a nonempty array.","es":"Calcula el promedio aritmético de un arreglo no vacío.","body":"a = [2, 4, 6]\nshow stats.mean(a)","out":"4.000000","noteEn":"","noteEs":""},"stats.minimum":{"en":"Find the smallest element of a nonempty array.","es":"Busca el menor elemento de un arreglo no vacío.","body":"a = [2, 4, 6]\nshow stats.minimum(a)","out":"2","noteEn":"","noteEs":""},"stats.maximum":{"en":"Find the largest element of a nonempty array.","es":"Busca el mayor elemento de un arreglo no vacío.","body":"a = [2, 4, 6]\nshow stats.maximum(a)","out":"6","noteEn":"","noteEs":""},"stats.variance":{"en":"Calculate population variance (divide by n).","es":"Calcula la varianza poblacional (divide entre n).","body":"a = [2, 4]\nshow stats.variance(a)","out":"1.000000","noteEn":"","noteEs":""},"stats.deviation":{"en":"Calculate population standard deviation.","es":"Calcula la desviación estándar poblacional.","body":"a = [2, 4]\nshow stats.deviation(a)","out":"1.000000","noteEn":"","noteEs":""},"stats.total":{"en":"Sum all array elements.","es":"Suma todos los elementos del arreglo.","body":"a = [2, 4, 6]\nshow stats.total(a)","out":"12","noteEn":"","noteEs":""},"system.platform":{"en":"Return the current target platform name.","es":"Devuelve el nombre de la plataforma de ejecución.","body":"show system.platform()","out":null,"noteEn":"Examples: windows, linux or web on the corresponding target.","noteEs":"Ejemplos: windows, linux o web según el destino."},"system.architecture":{"en":"Return the target architecture name.","es":"Devuelve el nombre de la arquitectura de ejecución.","body":"show system.architecture()","out":null,"noteEn":"Native x86_64; web target wasm32 where the adapter is enabled.","noteEs":"x86_64 nativo; wasm32 en la web cuando el adaptador está habilitado."},"system.compiler":{"en":"Return the compiler version string.","es":"Devuelve el texto con la versión del compilador.","body":"show system.compiler()","out":null,"noteEn":"","noteEs":""},"system.is_windows":{"en":"Check whether the target is Windows.","es":"Comprueba si el destino es Windows.","body":"show system.is_windows()","out":null,"noteEn":"","noteEs":""},"system.is_linux":{"en":"Check whether the target is Linux.","es":"Comprueba si el destino es Linux.","body":"show system.is_linux()","out":null,"noteEn":"","noteEs":""},"testing.equal_int":{"en":"Assert that two integers are equal; return true when they match.","es":"Comprueba que dos enteros sean iguales; devuelve true si coinciden.","body":"show testing.equal_int(2 + 3, 5)","out":"true","noteEn":"A mismatch triggers an assertion rather than returning false.","noteEs":"Una diferencia provoca una aserción en vez de devolver false."},"testing.equal_text":{"en":"Assert that two strings are equal.","es":"Comprueba que dos textos sean iguales.","body":"show testing.equal_text(\"TRI\" + \"POL\", \"TRIPOL\")","out":"true","noteEn":"","noteEs":""},"testing.equal_bool":{"en":"Assert that two boolean values are equal.","es":"Comprueba que dos valores booleanos sean iguales.","body":"show testing.equal_bool(5 > 2, true)","out":"true","noteEn":"","noteEs":""},"testing.near":{"en":"Assert that a decimal is within a nonnegative tolerance of the expected value.","es":"Comprueba que un decimal esté dentro de una tolerancia no negativa del valor esperado.","body":"show testing.near(3.14, 3.141, 0.01)","out":"true","noteEn":"","noteEs":""},"time.now_ms":{"en":"Read a monotonic timestamp in milliseconds.","es":"Lee una marca de tiempo monotónica en milisegundos.","body":"show time.now_ms()","out":null,"noteEn":"Not a calendar date or Unix timestamp.","noteEs":"No es una fecha ni una marca de tiempo Unix."},"time.elapsed":{"en":"Calculate milliseconds elapsed since a previous timestamp.","es":"Calcula los milisegundos transcurridos desde una marca anterior.","body":"start = time.now_ms()\nshow time.elapsed(start) >= 0","out":"true","noteEn":"","noteEs":""},"time.sleep":{"en":"Pause execution for a number of milliseconds.","es":"Pausa la ejecución durante varios milisegundos.","body":"time.sleep(100)\nshow \"Ready\"","out":"Ready","noteEn":"Browser sleep requires an isolated worker with the relevant capability.","noteEs":"La pausa web requiere un Worker aislado con la capacidad correspondiente."},"time.seconds":{"en":"Convert milliseconds into decimal seconds.","es":"Convierte milisegundos en segundos decimales.","body":"show time.seconds(2500)","out":"2.500000","noteEn":"","noteEs":""},"time.now_ns":{"en":"Read a high-resolution monotonic timestamp in nanoseconds.","es":"Lee una marca monotónica de alta resolución en nanosegundos.","body":"show time.now_ns()","out":null,"noteEn":"Origin and precision depend on the target.","noteEs":"El origen y la precisión dependen del destino."},"time.elapsed_ns":{"en":"Calculate nanoseconds elapsed since a previous timestamp.","es":"Calcula los nanosegundos transcurridos desde una marca anterior.","body":"start = time.now_ns()\nshow time.elapsed_ns(start) >= 0","out":"true","noteEn":"","noteEs":""},"ui.message":{"en":"Show an informational dialog and report whether it was acknowledged.","es":"Muestra un diálogo informativo e indica si fue aceptado.","body":"show ui.message(\"TRIPOL\", \"Hello!\")","out":null,"noteEn":"Native Windows, ASCII text only; result depends on the user.","noteEs":"Windows nativo, solo ASCII; el resultado depende del usuario."},"ui.confirm":{"en":"Ask a yes/no question and return true for Yes.","es":"Hace una pregunta de sí o no y devuelve true al elegir Sí.","body":"show ui.confirm(\"Continue?\", \"Start the demo?\")","out":null,"noteEn":"Native Windows, ASCII text only.","noteEs":"Windows nativo, solo texto ASCII."},"ui.form":{"en":"Open a modal form and read text entered by the user.","es":"Abre un formulario modal y lee el texto introducido.","body":"name = ui.form(\"Profile\", \"Name\", \"Save\")\nshow name","out":null,"noteEn":"Native Windows, ASCII labels; input depends on the user.","noteEs":"Windows nativo, etiquetas ASCII; la entrada depende del usuario."},"ui.warning":{"en":"Show a warning dialog.","es":"Muestra un diálogo de advertencia.","body":"show ui.warning(\"Warning\", \"Check your input\")","out":null,"noteEn":"Native Windows, ASCII text only.","noteEs":"Windows nativo, solo ASCII."},"ui.error":{"en":"Show an error dialog.","es":"Muestra un diálogo de error.","body":"show ui.error(\"Error\", \"Invalid input\")","out":null,"noteEn":"Native Windows, ASCII text only.","noteEs":"Windows nativo, solo ASCII."},"ui.retry":{"en":"Ask whether to retry; return true when Retry is selected.","es":"Pregunta si se desea reintentar; devuelve true al elegir Reintentar.","body":"show ui.retry(\"Retry\", \"Try again?\")","out":null,"noteEn":"Native Windows, ASCII text only.","noteEs":"Windows nativo, solo ASCII."},"ui.choose":{"en":"Display Yes, No and Cancel choices and return the selected code.","es":"Muestra las opciones Sí, No y Cancelar y devuelve el código elegido.","body":"choice = ui.choose(\"Save\", \"Save changes?\")\nshow choice","out":null,"noteEn":"Native Windows: Yes = 6, No = 7, Cancel = 2.","noteEs":"Windows nativo: Sí = 6, No = 7, Cancelar = 2."},"validate.digit":{"en":"Check whether an ASCII byte represents a digit.","es":"Comprueba si un byte ASCII representa un dígito.","body":"show validate.digit(57)","out":"true","noteEn":"","noteEs":""},"validate.letter":{"en":"Check whether an ASCII byte represents an English letter.","es":"Comprueba si un byte ASCII representa una letra inglesa.","body":"show validate.letter(65)","out":"true","noteEn":"","noteEs":""},"validate.whitespace":{"en":"Check for space, tab, line feed or carriage return.","es":"Comprueba si es espacio, tabulador, salto de línea o retorno de carro.","body":"show validate.whitespace(32)","out":"true","noteEn":"","noteEs":""},"validate.integer":{"en":"Check the spelling of a signed integer, without checking its numeric range.","es":"Comprueba la escritura de un entero con signo, sin comprobar su rango numérico.","body":"show validate.integer(\"-42\")\nshow validate.integer(\"3.5\")","out":"true\nfalse","noteEn":"Use errors.is_int() to check the full int64 range.","noteEs":"Usa errors.is_int() para comprobar todo el rango int64."},"validate.ascii":{"en":"Check whether every byte is in the ASCII range.","es":"Comprueba si todos los bytes pertenecen al rango ASCII.","body":"show validate.ascii(\"TRIPOL\")\nshow validate.ascii(\"á\")","out":"true\nfalse","noteEn":"","noteEs":""},"validate.identifier":{"en":"Check an ASCII identifier beginning with a letter or underscore.","es":"Comprueba un identificador ASCII que comienza por letra o guion bajo.","body":"show validate.identifier(\"player_1\")\nshow validate.identifier(\"1player\")","out":"true\nfalse","noteEn":"Does not check whether the name is a reserved keyword.","noteEs":"No comprueba si el nombre es una palabra reservada."},"vector.dot2":{"en":"Calculate the 2D dot product.","es":"Calcula el producto escalar de dos vectores 2D.","body":"show vector.dot2(1.0, 2.0, 3.0, 4.0)","out":"11.000000","noteEn":"","noteEs":""},"vector.cross2":{"en":"Calculate the signed scalar 2D cross product.","es":"Calcula el producto cruzado escalar con signo de dos vectores 2D.","body":"show vector.cross2(1.0, 0.0, 0.0, 1.0)","out":"1.000000","noteEn":"","noteEs":""},"vector.length2":{"en":"Calculate the length of a 2D vector.","es":"Calcula la longitud de un vector 2D.","body":"show vector.length2(3.0, 4.0)","out":"5.000000","noteEn":"","noteEs":""},"vector.distance2":{"en":"Calculate the distance between two 2D points.","es":"Calcula la distancia entre dos puntos 2D.","body":"show vector.distance2(0.0, 0.0, 3.0, 4.0)","out":"5.000000","noteEn":"","noteEs":""},"vector.normalized_x":{"en":"Return the x component after normalizing a nonzero vector.","es":"Devuelve la componente x después de normalizar un vector no nulo.","body":"show vector.normalized_x(3.0, 4.0)","out":"0.600000","noteEn":"","noteEs":""},"vector.normalized_y":{"en":"Return the y component after normalizing a nonzero vector.","es":"Devuelve la componente y después de normalizar un vector no nulo.","body":"show vector.normalized_y(3.0, 4.0)","out":"0.800000","noteEn":"","noteEs":""},"vector.scale":{"en":"Return a new integer array multiplied by a scalar.","es":"Devuelve un arreglo nuevo de enteros multiplicados por un escalar.","body":"a = [1, 2, 3]\nshow vector.scale(a, 2)","out":"[2, 4, 6]","noteEn":"","noteEs":""},"stack.create":{"en":"Create an empty bounded LIFO stack.","es":"Crea una pila LIFO vacía de capacidad fija.","body":"s = stack.create(3)\nshow stack.size(s)","out":"0","noteEn":"","noteEs":""},"stack.capacity":{"en":"Return the maximum number of stored integers.","es":"Devuelve la cantidad máxima de enteros almacenados.","body":"s = stack.create(3)\nshow stack.capacity(s)","out":"3","noteEn":"","noteEs":""},"stack.size":{"en":"Return the number of stored integers.","es":"Devuelve la cantidad de enteros almacenados.","body":"s = stack.create(3)\nstack.push(s, 10)\nshow stack.size(s)","out":"1","noteEn":"","noteEs":""},"stack.push":{"en":"Add an integer; return false when the container is full.","es":"Añade un entero; devuelve false cuando el contenedor está lleno.","body":"s = stack.create(3)\nshow stack.push(s, 10)","out":"true","noteEn":"","noteEs":""},"stack.peek":{"en":"Read the last inserted value without removing it.","es":"Lee el último valor insertado sin eliminarlo.","body":"s = stack.create(3)\nstack.push(s, 10)\nstack.push(s, 20)\nshow stack.peek(s)","out":"20","noteEn":"Must not be empty.","noteEs":"No debe estar vacío."},"stack.pop":{"en":"Remove and return the last inserted value.","es":"Elimina y devuelve el último valor insertado.","body":"s = stack.create(3)\nstack.push(s, 10)\nstack.push(s, 20)\nshow stack.pop(s)","out":"20","noteEn":"Must not be empty.","noteEs":"No debe estar vacío."},"stack.clear":{"en":"Remove all logical entries and return the previous count.","es":"Elimina todas las entradas lógicas y devuelve la cantidad anterior.","body":"s = stack.create(3)\nstack.push(s, 10)\nstack.push(s, 20)\nshow stack.clear(s)\nshow stack.size(s)","out":"2\n0","noteEn":"","noteEs":""},"queue.create":{"en":"Create an empty bounded FIFO queue.","es":"Crea una cola FIFO vacía de capacidad fija.","body":"q = queue.create(3)\nshow queue.size(q)","out":"0","noteEn":"","noteEs":""},"queue.capacity":{"en":"Return the maximum number of stored integers.","es":"Devuelve la cantidad máxima de enteros almacenados.","body":"q = queue.create(3)\nshow queue.capacity(q)","out":"3","noteEn":"","noteEs":""},"queue.size":{"en":"Return the number of stored integers.","es":"Devuelve la cantidad de enteros almacenados.","body":"q = queue.create(3)\nqueue.push(q, 10)\nshow queue.size(q)","out":"1","noteEn":"","noteEs":""},"queue.push":{"en":"Add an integer; return false when the container is full.","es":"Añade un entero; devuelve false cuando el contenedor está lleno.","body":"q = queue.create(3)\nshow queue.push(q, 10)","out":"true","noteEn":"","noteEs":""},"queue.peek":{"en":"Read the oldest value without removing it.","es":"Lee el valor más antiguo sin eliminarlo.","body":"q = queue.create(3)\nqueue.push(q, 10)\nqueue.push(q, 20)\nshow queue.peek(q)","out":"10","noteEn":"Must not be empty.","noteEs":"No debe estar vacío."},"queue.pop":{"en":"Remove and return the oldest value.","es":"Elimina y devuelve el valor más antiguo.","body":"q = queue.create(3)\nqueue.push(q, 10)\nqueue.push(q, 20)\nshow queue.pop(q)","out":"10","noteEn":"Must not be empty.","noteEs":"No debe estar vacío."},"queue.clear":{"en":"Remove all logical entries and return the previous count.","es":"Elimina todas las entradas lógicas y devuelve la cantidad anterior.","body":"q = queue.create(3)\nqueue.push(q, 10)\nqueue.push(q, 20)\nshow queue.clear(q)\nshow queue.size(q)","out":"2\n0","noteEn":"","noteEs":""},"bitset.create":{"en":"Create an empty compact set with a fixed number of bit positions.","es":"Crea un conjunto compacto vacío con una cantidad fija de posiciones.","body":"b = bitset.create(100)\nshow bitset.count(b)","out":"0","noteEn":"","noteEs":""},"bitset.capacity":{"en":"Return the number of addressable bit positions.","es":"Devuelve la cantidad de posiciones de bits disponibles.","body":"b = bitset.create(100)\nshow bitset.capacity(b)","out":"100","noteEn":"","noteEs":""},"bitset.contains":{"en":"Check whether an indexed bit is set.","es":"Comprueba si está activado un bit por su índice.","body":"b = bitset.create(100)\nbitset.add(b, 65)\nshow bitset.contains(b, 65)","out":"true","noteEn":"","noteEs":""},"bitset.add":{"en":"Set a bit and return true only if it was previously unset.","es":"Activa un bit y devuelve true solo si antes estaba desactivado.","body":"b = bitset.create(100)\nshow bitset.add(b, 65)\nshow bitset.add(b, 65)","out":"true\nfalse","noteEn":"","noteEs":""},"bitset.remove":{"en":"Clear a bit and return whether it was previously set.","es":"Desactiva un bit y devuelve si antes estaba activado.","body":"b = bitset.create(100)\nbitset.add(b, 65)\nshow bitset.remove(b, 65)","out":"true","noteEn":"","noteEs":""},"bitset.count":{"en":"Count the active bits in the set.","es":"Cuenta los bits activados en el conjunto.","body":"b = bitset.create(100)\nbitset.add(b, 1)\nbitset.add(b, 65)\nshow bitset.count(b)","out":"2","noteEn":"","noteEs":""},"profiler.start":{"en":"Start measuring monotonic elapsed time in nanoseconds.","es":"Inicia una medición de tiempo monotónico en nanosegundos.","body":"start = profiler.start()\nshow profiler.elapsed(start) >= 0","out":"true","noteEn":"Measures elapsed time, not CPU or heap samples.","noteEs":"Mide tiempo transcurrido, no muestras de CPU ni de memoria."},"profiler.elapsed":{"en":"Return elapsed nanoseconds since a profiler timestamp.","es":"Devuelve los nanosegundos transcurridos desde una marca del perfilador.","body":"start = profiler.start()\ntotal = 0\nfor i in range(100) {total += i}\nshow total\nshow profiler.elapsed(start)","out":null,"noteEn":"The sum is 4950; the time varies by execution.","noteEs":"La suma es 4950; el tiempo varía según la ejecución."}};
